INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-diag-csa_q1', 'ap-diag-csa', 1, false, 'B', 'Java Syntax', 'easy', 'What is `7 / 2` in Java?', '["3.5","3","3.0","Error"]'::jsonb, 'Integer division truncates decimal.'),
  ('ap-diag-csa_q2', 'ap-diag-csa', 2, false, 'B', 'OOP', 'medium', 'Which keyword is used to inherit a class in Java?', '["implements","extends","super","this"]'::jsonb, '`extends` keyword is used for class inheritance.'),
  ('ap-diag-csa_q3', 'ap-diag-csa', 3, false, 'C', 'Primitives', 'easy', 'Which of the following is a primitive type in Java?', '["String","Integer","int","Array"]'::jsonb, '''int'' is a primitive; String, Integer, and Array are reference types.'),
  ('ap-diag-csa_q4', 'ap-diag-csa', 4, false, 'B', 'Operators', 'easy', 'What is the result of 7 % 3 in Java?', '["2","1","3","0"]'::jsonb, '7 divided by 3 is 2 remainder 1, so 7 % 3 = 1.'),
  ('ap-diag-csa_q5', 'ap-diag-csa', 5, false, 'B', 'Conditionals', 'easy', 'Which keyword chain is used for multiple conditions in Java?', '["elif","else if","elseif","otherwise"]'::jsonb, 'Java uses ''else if'' (two separate words) for chained conditions.'),
  ('ap-diag-csa_q6', 'ap-diag-csa', 6, false, 'B', 'Loops', 'easy', 'How many times does this loop execute? for(int i=0; i<5; i++)', '["4","5","6","0"]'::jsonb, 'i goes 0,1,2,3,4 — 5 iterations total.'),
  ('ap-diag-csa_q7', 'ap-diag-csa', 7, false, 'B', 'Arrays', 'easy', 'What is the index of the first element in a Java array?', '["1","0","-1","Depends on declaration"]'::jsonb, 'Java arrays are 0-indexed; the first element is at index 0.'),
  ('ap-diag-csa_q8', 'ap-diag-csa', 8, false, 'B', 'Arrays', 'medium', 'What does arr.length return for: int[] arr = new int[10]?', '["9","10","11","Error"]'::jsonb, 'arr.length returns the total number of elements, which is 10.'),
  ('ap-diag-csa_q9', 'ap-diag-csa', 9, false, 'C', 'OOP', 'medium', 'Which keyword creates an object from a class in Java?', '["class","object","new","create"]'::jsonb, 'The ''new'' keyword allocates memory and creates an instance of a class.'),
  ('ap-diag-csa_q10', 'ap-diag-csa', 10, false, 'B', 'OOP', 'medium', 'What is encapsulation in OOP?', '["Inheriting methods from a parent","Hiding data using private fields and public methods","Creating multiple methods with the same name","A class with no constructor"]'::jsonb, 'Encapsulation bundles data and restricts direct access using private fields.'),
  ('ap-diag-csa_q11', 'ap-diag-csa', 11, false, 'B', 'Inheritance', 'medium', 'In Java, a subclass can extend:', '["Multiple classes","Only one superclass","Any number of interfaces only","No class"]'::jsonb, 'Java does not support multiple class inheritance; a class can only extend one superclass.'),
  ('ap-diag-csa_q12', 'ap-diag-csa', 12, false, 'B', 'Recursion', 'medium', 'What is the base case of the factorial function?', '["$n = = 1$","$n = = 0 returns 1$","n < 0","$n = = n-1$"]'::jsonb, 'factorial(0) = 1 is the standard base case to stop recursion.'),
  ('ap-diag-csa_q13', 'ap-diag-csa', 13, false, 'C', 'Recursion', 'hard', 'What does f(4) return? int f(int n){ if(n<=1) return 1; return n*f(n-1); }', '["4","12","24","16"]'::jsonb, 'f(4) = 4*3*2*1 = 24 (factorial of 4).'),
  ('ap-diag-csa_q14', 'ap-diag-csa', 14, false, 'B', 'ArrayList', 'medium', 'Which method removes an element from an ArrayList by index?', '[".delete(i)",".remove(i)",".pop(i)",".erase(i)"]'::jsonb, 'ArrayList.remove(int index) removes the element at the given index.'),
  ('ap-diag-csa_q15', 'ap-diag-csa', 15, false, 'B', 'Strings', 'easy', 'What does str.length() return for str = "hello"?', '["4","5","6","Error"]'::jsonb, '''hello'' has 5 characters, so length() returns 5.'),
  ('ap-diag-csa_q16', 'ap-diag-csa', 16, false, 'B', 'Strings', 'medium', 'What does str.substring(1, 3) return for str = "abcde"?', '["ab","bc","abc","bcd"]'::jsonb, 'substring(1,3) extracts characters at indices 1 and 2, giving ''bc''.'),
  ('ap-diag-csa_q17', 'ap-diag-csa', 17, false, 'C', 'Static', 'medium', 'A static method in Java:', '["Requires an object to call","Can access instance variables freely","Belongs to the class, not instances","Cannot have parameters"]'::jsonb, 'Static methods belong to the class and can be called without creating an instance.'),
  ('ap-diag-csa_q18', 'ap-diag-csa', 18, false, 'C', 'Exception Handling', 'medium', 'Which block always executes after try/catch in Java?', '["catch","throw","finally","else"]'::jsonb, 'The ''finally'' block always executes regardless of whether an exception was thrown.'),
  ('ap-diag-csa_q19', 'ap-diag-csa', 19, false, 'B', '2D Arrays', 'medium', 'For int[][] grid = new int[3][4], how many total elements are there?', '["7","12","3","4"]'::jsonb, '3 rows x 4 columns = 12 total elements.'),
  ('ap-diag-csa_q20', 'ap-diag-csa', 20, false, 'C', 'Interfaces', 'medium', 'A Java interface:', '["Can be instantiated directly","Contains only method implementations","Defines abstract methods that implementing classes must provide","Extends multiple classes"]'::jsonb, 'An interface defines a contract of method signatures that implementing classes must fulfill.'),
  ('ap-diag-csa_q21', 'ap-diag-csa', 21, false, 'B', 'Polymorphism', 'hard', 'Which term describes a method behaving differently based on the calling object?', '["Encapsulation","Polymorphism","Abstraction","Compilation"]'::jsonb, 'Polymorphism allows one interface to be used for different underlying data types or classes.'),
  ('ap-diag-csa_q22', 'ap-diag-csa', 22, false, 'B', 'Boolean', 'easy', 'What is the value of: true && false || true?', '["false","true","null","Error"]'::jsonb, '&& has higher precedence: (true && false) = false; false || true = true.'),
  ('ap-diag-csa_q23', 'ap-diag-csa', 23, false, 'B', 'Type Casting', 'medium', 'What is the result of (int)(7.9) in Java?', '["8","7","7.9","Error"]'::jsonb, 'Casting to int truncates (does not round): result is 7.'),
  ('ap-diag-csa_q24', 'ap-diag-csa', 24, false, 'A', 'For-each', 'easy', 'Which loop iterates over each element in array arr?', '["for(int i : arr)","for(i in arr)","foreach(int i, arr)","for(arr -> i)"]'::jsonb, 'Java''s enhanced for-loop syntax is ''for(type variable : array)''.'),
  ('ap-diag-csa_q25', 'ap-diag-csa', 25, false, 'B', 'Math class', 'easy', 'Which Math method returns the larger of two values?', '["Math.large()","Math.max()","Math.top()","Math.high()"]'::jsonb, 'Math.max(a, b) returns the greater of a and b.'),
  ('ap-diag-csa_q26', 'ap-diag-csa', 26, false, 'B', 'Overloading', 'medium', 'Method overloading means:', '["A subclass redefines a parent method","Multiple methods share the same name with different parameters","A method calls itself","Hiding instance variables"]'::jsonb, 'Overloading allows multiple methods with the same name but different parameter signatures.'),
  ('ap-diag-csa_q27', 'ap-diag-csa', 27, false, 'B', 'Constructors', 'medium', 'What is a default constructor?', '["A constructor that takes parameters","A no-arg constructor provided by Java if none is defined","A static method","A private method"]'::jsonb, 'Java provides a no-argument default constructor automatically if no constructor is explicitly defined.'),
  ('ap-diag-csa_q28', 'ap-diag-csa', 28, false, 'C', 'Sorting', 'hard', 'Worst-case time complexity of Selection Sort is:', '["O(n)","O(n log n)","O(n squared)","O(log n)"]'::jsonb, 'Selection Sort always performs O(n^2) comparisons regardless of input order.'),
  ('ap-diag-csa_q29', 'ap-diag-csa', 29, false, 'B', 'Binary Search', 'hard', 'Binary search requires the array to be:', '["Unsorted","Sorted","Filled with unique values","Of even length"]'::jsonb, 'Binary search only works correctly on a sorted array.'),
  ('ap-diag-csa_q30', 'ap-diag-csa', 30, false, 'B', 'OOP', 'hard', 'The ''super'' keyword in Java is used to:', '["Call a child class method","Access the parent class constructor or methods","Declare a static field","Create an interface"]'::jsonb, '''super'' refers to the parent class and can be used to call its constructor or methods.'),
  ('ap-diag-stats_q1', 'ap-diag-stats', 1, false, 'B', 'Data', 'easy', 'Which measure of center is resistant to extreme outliers?', '["Mean","Median","Standard Deviation","Range"]'::jsonb, 'The median is resistant to extreme values.'),
  ('ap-diag-stats_q2', 'ap-diag-stats', 2, false, 'B', 'Descriptive Statistics', 'easy', 'The mean of {2, 4, 6, 8, 10} is:', '["5","6","7","8"]'::jsonb, 'Sum = 30, n = 5, mean = 30/5 = 6.'),
  ('ap-diag-stats_q3', 'ap-diag-stats', 3, false, 'B', 'Descriptive Statistics', 'easy', 'The median of {3, 7, 5, 1, 9} is:', '["3","5","7","1"]'::jsonb, 'Sorted: {1, 3, 5, 7, 9}. Middle value = 5.'),
  ('ap-diag-stats_q4', 'ap-diag-stats', 4, false, 'C', 'Descriptive Statistics', 'easy', 'Which measure of spread is most resistant to outliers?', '["Range","Standard deviation","IQR","Variance"]'::jsonb, 'IQR uses the middle 50% of data and is not affected by extreme values.'),
  ('ap-diag-stats_q5', 'ap-diag-stats', 5, false, 'B', 'Probability', 'easy', 'If P(A) = 0.4 and P(B) = 0.3 and A, B are independent, P(A and B) = ?', '["0.7","0.12","0.1","0.5"]'::jsonb, 'For independent events: P(A and B) = P(A) * P(B) = 0.4 * 0.3 = 0.12.'),
  ('ap-diag-stats_q6', 'ap-diag-stats', 6, false, 'A', 'Probability', 'medium', 'P(A or B) = 0.7, P(A) = 0.4, P(B) = 0.5. What is P(A and B)?', '["0.2","0.3","0.1","0.9"]'::jsonb, 'P(A or B) = P(A)$+P$(B)$-P$(A and B) => 0.7 = 0.9 - P(A and B) => P(A and B) = 0.2.'),
  ('ap-diag-stats_q7', 'ap-diag-stats', 7, false, 'A', 'Normal Distribution', 'medium', 'Approximately what percentage of data falls within 1 standard deviation in a normal distribution?', '["68%","95%","99.7%","50%"]'::jsonb, 'The empirical rule: ~68% of data falls within +-1 sigma of the mean.'),
  ('ap-diag-stats_q8', 'ap-diag-stats', 8, false, 'B', 'Normal Distribution', 'medium', 'z-score for a data point of 80, mean=70, SD=5?', '["1","2","10","-2"]'::jsonb, 'z = (80 - 70)/5 = 2.'),
  ('ap-diag-stats_q9', 'ap-diag-stats', 9, false, 'A', 'Sampling', 'medium', 'A simple random sample (SRS) ensures:', '["Every individual has an equal chance of selection","The sample is perfectly representative","No bias exists","Stratification by group"]'::jsonb, 'In an SRS, every individual has an equal probability of being selected.'),
  ('ap-diag-stats_q10', 'ap-diag-stats', 10, false, 'B', 'Hypothesis Testing', 'medium', 'The null hypothesis (H0) typically states:', '["There is a significant effect","There is no effect or no difference","The alternative is true","p < 0.05"]'::jsonb, 'H0 is the claim of no effect or no difference that we test against.'),
  ('ap-diag-stats_q11', 'ap-diag-stats', 11, false, 'B', 'Hypothesis Testing', 'medium', 'A p-value of 0.03 with alpha = 0.05 means:', '["Fail to reject H0","Reject H0","Accept H1 definitively","Repeat the test"]'::jsonb, 'Since p-value (0.03) < alpha (0.05), we reject the null hypothesis.'),
  ('ap-diag-stats_q12', 'ap-diag-stats', 12, false, 'C', 'Confidence Intervals', 'medium', 'A 95% confidence interval means:', '["95% of data falls in the interval","The true parameter is definitely in this interval","If repeated many times, 95% of such intervals contain the true parameter","The sample mean equals the population mean"]'::jsonb, 'Confidence intervals are interpreted in terms of repeated sampling procedures.'),
  ('ap-diag-stats_q13', 'ap-diag-stats', 13, false, 'B', 'Regression', 'medium', 'In y-hat = 3 + 2x, what does the slope 2 represent?', '["The y-intercept","For each 1-unit increase in x, y increases by 2 on average","The correlation coefficient","The predicted value when x = 0"]'::jsonb, 'The slope represents the average change in the response variable for each 1-unit increase in the explanatory variable.'),
  ('ap-diag-stats_q14', 'ap-diag-stats', 14, false, 'C', 'Regression', 'medium', 'Correlation coefficient r = -0.85 indicates:', '["Weak positive relationship","Strong positive relationship","Strong negative relationship","No relationship"]'::jsonb, 'r close to -1 indicates a strong negative linear relationship between variables.'),
  ('ap-diag-stats_q15', 'ap-diag-stats', 15, false, 'B', 'Categorical Data', 'easy', 'A chi-square test is used to analyze:', '["Means of two groups","Association between categorical variables","Correlation of quantitative variables","Differences in medians"]'::jsonb, 'Chi-square tests analyze whether a significant association exists between categorical variables.'),
  ('ap-diag-stats_q16', 'ap-diag-stats', 16, false, 'A', 'Binomial', 'medium', 'For a binomial distribution with n=10, p=0.5, what is the mean?', '["5","2.5","10","0.5"]'::jsonb, 'Mean of binomial distribution = n*p = 10 * 0.5 = 5.'),
  ('ap-diag-stats_q17', 'ap-diag-stats', 17, false, 'D', 'Binomial', 'medium', 'Which condition is NOT required for a binomial setting?', '["Fixed number of trials","Independent trials","Same probability of success each trial","Continuous outcomes"]'::jsonb, 'Binomial requires discrete binary outcomes (success/failure), not continuous outcomes.'),
  ('ap-diag-stats_q18', 'ap-diag-stats', 18, false, 'B', 'Sampling Distributions', 'hard', 'As sample size increases, the standard error of the mean:', '["Increases","Decreases","Stays the same","Doubles"]'::jsonb, 'Standard error = sigma/sqrt(n). As n increases, standard error decreases.'),
  ('ap-diag-stats_q19', 'ap-diag-stats', 19, false, 'B', 'Two-sample Tests', 'hard', 'A two-sample t-test compares:', '["A sample mean to a known population mean","Means of two independent groups","A single proportion","Normality of a distribution"]'::jsonb, 'Two-sample t-test compares means from two separate, independent groups.'),
  ('ap-diag-stats_q20', 'ap-diag-stats', 20, false, 'B', 'Probability', 'medium', 'The complement of event A is:', '["A and B","Not A","A or B","A given B"]'::jsonb, 'The complement of A is the event that A does NOT occur: P(A-complement) = 1 - P(A).')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-diag-stats_q21', 'ap-diag-stats', 21, false, 'C', 'Descriptive Statistics', 'easy', 'Which plot best shows shape, center, and spread of a distribution?', '["Bar chart","Pie chart","Boxplot","Scatter plot"]'::jsonb, 'A boxplot displays the five-number summary revealing shape and spread.'),
  ('ap-diag-stats_q22', 'ap-diag-stats', 22, false, 'C', 'Experimental Design', 'medium', 'In a completely randomized experiment, subjects are assigned to groups:', '["Based on their scores","By stratification","Randomly","By researcher''s choice"]'::jsonb, 'Random assignment is the defining feature of a completely randomized experiment.'),
  ('ap-diag-stats_q23', 'ap-diag-stats', 23, false, 'B', 'Experimental Design', 'medium', 'The purpose of a control group is:', '["To receive the treatment","To provide a baseline for comparison","To maximize sample size","To eliminate all variability"]'::jsonb, 'A control group receives no treatment to serve as a baseline for comparison.'),
  ('ap-diag-stats_q24', 'ap-diag-stats', 24, false, 'B', 'Inference for Proportions', 'hard', 'A one-proportion z-test is used when:', '["Comparing two population means","Testing whether a population proportion equals a specific value","Testing independence of categorical variables","Comparing two variances"]'::jsonb, 'A one-proportion z-test tests whether a sample provides evidence that a population proportion differs from a claimed value.'),
  ('ap-diag-stats_q25', 'ap-diag-stats', 25, false, 'A', 'Normal Distribution', 'hard', 'If X ~ N(100, 225), what is P(X > 130)?', '["~0.023","~0.159","~0.5","~0.977"]'::jsonb, 'z = (130-100)/15 = 2. P(Z > 2) is approximately 0.023.'),
  ('ap-diag-stats_q26', 'ap-diag-stats', 26, false, 'B', 'Probability', 'medium', 'Two events are mutually exclusive if:', '["They are independent","They cannot occur simultaneously","Their probabilities sum to 1","One causes the other"]'::jsonb, 'Mutually exclusive events cannot happen at the same time: P(A and B) = 0.'),
  ('ap-diag-stats_q27', 'ap-diag-stats', 27, false, 'B', 'Regression', 'hard', 'R-squared = 0.81 means:', '["The correlation is 0.81","81% of variability in y is explained by x","$r = 0.81 squared$","The model predicts 81 data points correctly"]'::jsonb, 'R-squared represents the proportion of variation in the response variable explained by the regression model.'),
  ('ap-diag-stats_q28', 'ap-diag-stats', 28, false, 'B', 'Sampling', 'medium', 'Stratified random sampling:', '["Uses random clusters","Divides population into homogeneous groups then samples from each","Uses self-selected volunteers","Uses consecutive subjects"]'::jsonb, 'Stratified sampling divides the population into subgroups (strata) and randomly samples from each stratum.'),
  ('ap-diag-stats_q29', 'ap-diag-stats', 29, false, 'C', 'Descriptive Statistics', 'medium', 'Which statistic is most affected by extreme outliers?', '["Median","IQR","Mean","Mode"]'::jsonb, 'The mean uses all data values in its calculation and is heavily influenced by extreme values.'),
  ('ap-diag-stats_q30', 'ap-diag-stats', 30, false, 'B', 'Type I Error', 'hard', 'A Type I error occurs when you:', '["Fail to reject a false H0","Reject a true H0","Accept H1 with certainty","Set alpha too low"]'::jsonb, 'Type I error: rejecting the null hypothesis when it is actually true (false positive).'),
  ('ap-topic-csa-java_q1', 'ap-topic-csa-java', 1, false, 'B', 'Java Basics', 'easy', 'What is the result of `7 / 2` in Java?', '["3.5","3","3.0","Error"]'::jsonb, 'Integer division truncates decimal: 7 / 2 = 3.'),
  ('ap-topic-csa-java_q2', 'ap-topic-csa-java', 2, false, 'A', 'Java Fundamentals & Control Flow', 'easy', 'What is the value of `result` after executing: `int a = 7; int b = 2; double result = a / b;`?', '["3.0","3.5","3","4.0"]'::jsonb, 'Both `a` and `b` are integer variables, so `a / b` performs integer division yielding `3`. Then, assigning integer `3` to `double result` performs widening conversion to `3.0`.'),
  ('ap-topic-csa-java_q3', 'ap-topic-csa-java', 3, false, 'A', 'Java Fundamentals & Control Flow', 'medium', 'Consider the code snippet:
```java
String s = "AP Computer Science";
String sub = s.substring(3, 11);
```
What is the value of `sub`?', '["\"Computer\"","\"Compute\"","\" Computer\"","\"Computer \""]'::jsonb, 'In Java, `substring(beginIndex, endIndex)` extracts characters from `beginIndex` (inclusive) up to `endIndex` (exclusive). Index 3 is ''C'', index 10 is ''r'', and index 11 is '' ''. Thus, the characters from index 3 to 10 form `"Computer"`.'),
  ('ap-topic-csa-java_q4', 'ap-topic-csa-java', 4, false, 'A', 'Java Fundamentals & Control Flow', 'medium', 'Consider the loop:
```java
int count = 0;
for (int i = 1; i <= 5; i++) {
    for (int j = i; j <= 5; j++) {
        count++;
    }
}
```
What is the final value of `count`?', '["15","25","10","20"]'::jsonb, 'When $i = 1$, the inner loop runs 5 times ($j = 1..5$). When $i = 2$, 4 times. When $i = 3$, 3 times. When $i = 4$, 2 times. When $i = 5$, 1 time. Total executions = $5 + 4 + 3 + 2 + 1 = 15$.'),
  ('ap-topic-csa-java_q5', 'ap-topic-csa-java', 5, false, 'A', 'Java Fundamentals & Control Flow', 'medium', 'By De Morgan''s Laws, the boolean expression `!(a && (b || !c))` is equivalent to:', '["!a || (!b && c)","!a && (!b || c)","!a || !b || c","!a && !b && c"]'::jsonb, 'Applying De Morgan''s Law to the outer AND: `!(a && X) == !a || !X`. Here $X = (b \;||\; !c)$. Applying De Morgan''s Law to $!X$: `!(b || !c) == !b && !(!c) == !b && c`. Combining gives `!a || (!b && c)`.'),
  ('ap-topic-csa-java_q6', 'ap-topic-csa-java', 6, false, 'A', 'Java Fundamentals & Control Flow', 'hard', 'Consider the recursive method:
```java
public static int mystery(int n) {
    if (n <= 1) return 1;
    return n + mystery(n - 2);
}
```
What is the return value of `mystery(7)`?', '["16","15","28","12"]'::jsonb, 'Trace the recursive calls: `mystery(7) = 7 + mystery(5)`. `mystery(5) = 5 + mystery(3)`. `mystery(3) = 3 + mystery(1)`. Base case: `mystery(1) = 1`. Back-substituting: $3 + 1 = 4$; $5 + 4 = 9$; $7 + 9 = 16$.'),
  ('ap-topic-csa-java_q7', 'ap-topic-csa-java', 7, false, 'A', 'Java Fundamentals & Control Flow', 'medium', 'What is printed by the following code?
```java
int[] arr = {10, 20, 30, 40, 50};
for (int i = 0; i < arr.length - 1; i++) {
    arr[i] = arr[i + 1];
}
System.out.println(arr[0] + " " + arr[4]);
```', '["20 50","20 40","10 50","20 20"]'::jsonb, 'The loop shifts each element one index to the left: `arr[0]` becomes `arr[1]` (20), `arr[1]` becomes `arr[2]` (30), `arr[2]` becomes 40, `arr[3]` becomes 50. The loop terminates before modifying `arr[4]`, so `arr[4]` remains 50. Output is `20 50`.'),
  ('ap-topic-csa-java_q8', 'ap-topic-csa-java', 8, false, 'A', 'Java Fundamentals & Control Flow', 'medium', 'Consider the `ArrayList<Integer>` operations:
```java
ArrayList<Integer> list = new ArrayList<>();
list.add(10);
list.add(20);
list.add(1, 30);
list.remove(0);
System.out.println(list);
```
What is printed?', '["[30, 20]","[10, 30]","[20, 30]","[30, 10]"]'::jsonb, 'Initially `list` is empty. `add(10)` -> `[10]`. `add(20)` -> `[10, 20]`. `add(1, 30)` inserts 30 at index 1 -> `[10, 30, 20]`. `remove(0)` removes element at index 0 (10) -> `[30, 20]`.'),
  ('ap-topic-csa-java_q9', 'ap-topic-csa-java', 9, false, 'A', 'Java Fundamentals & Control Flow', 'hard', 'Consider the binary search method on a sorted array of 64 elements. In the worst case, what is the maximum number of comparisons needed to locate a target element or confirm it is absent?', '["7","6","32","64"]'::jsonb, 'Binary search halves the search space at each iteration. For $N = 64$ elements, the maximum number of comparisons is $\lfloor \log_2(64) \rfloor + 1 = 6 + 1 = 7$.'),
  ('ap-topic-csa-java_q10', 'ap-topic-csa-java', 10, false, 'A', 'Java Fundamentals & Control Flow', 'medium', 'What is the output of the following loop?
```java
int x = 1;
while (x < 16) {
    x *= 2;
}
System.out.println(x);
```', '["16","32","8","15"]'::jsonb, 'Trace $x$: starts at 1. $1 < 16 \implies x = 2$. $2 < 16 \implies x = 4$. $4 < 16 \implies x = 8$. $8 < 16 \implies x = 16$. Now $16 < 16$ is false, so loop terminates. `System.out.println(x)` prints 16.'),
  ('ap-topic-csa-java_q11', 'ap-topic-csa-java', 11, false, 'A', 'Java Fundamentals & Control Flow', 'medium', 'Which of the following correctly generates a random integer between 10 and 50 inclusive using `Math.random()`?', '["(int)(Math.random() * 41) + 10","(int)(Math.random() * 50) + 10","(int)(Math.random() * 40) + 10","(int)(Math.random() * 51)"]'::jsonb, 'The standard formula for a random integer in $[\text{min}, \text{max}]$ inclusive is `(int)(Math.random() * (max - min + 1)) + min`. Here $\text{max} - \text{min} + 1 = 50 - 10 + 1 = 41$. Thus `(int)(Math.random() * 41) + 10` produces numbers from 10 to 50.'),
  ('ap-topic-csa-java_q12', 'ap-topic-csa-java', 12, false, 'A', 'Java Fundamentals & Control Flow', 'hard', 'Consider the 2D array:
```java
int[][] mat = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
int sum = 0;
for (int r = 0; r < mat.length; r++) {
    sum += mat[r][mat.length - 1 - r];
}
```
What is the value of `sum`?', '["15","12","18","21"]'::jsonb, 'The expression accesses the secondary diagonal of the 3x3 matrix: when $r=0$, `mat[0][2]` = 3; when $r=1$, `mat[1][1]` = 5; when $r=2$, `mat[2][0]` = 7. Sum = $3 + 5 + 7 = 15$.'),
  ('ap-topic-csa-java_q13', 'ap-topic-csa-java', 13, false, 'A', 'Java Fundamentals & Control Flow', 'medium', 'Consider `String s1 = "apple"; String s2 = new String("apple");`. Which comparison evaluates to `true`?', '["s1.equals(s2) only","s1 == s2 only","Both s1 == s2 and s1.equals(s2)","Neither s1 == s2 nor s1.equals(s2)"]'::jsonb, '`==` compares memory references. Because `s2` is created with the `new` operator, it refers to a distinct object in heap memory, so `s1 == s2` is `false`. `.equals()` compares the character contents, which are identical, so `s1.equals(s2)` is `true`.'),
  ('ap-topic-csa-java_q14', 'ap-topic-csa-java', 14, false, 'A', 'Java Fundamentals & Control Flow', 'medium', 'Which sorting algorithm repeatedly finds the minimum element from the unsorted portion of an array and places it at the beginning?', '["Selection Sort","Insertion Sort","Merge Sort","Quick Sort"]'::jsonb, 'Selection Sort divides the list into sorted and unsorted portions, finding the smallest element in the unsorted section in each pass and swapping it into the next position.'),
  ('ap-topic-csa-java_q15', 'ap-topic-csa-java', 15, false, 'A', 'Java Fundamentals & Control Flow', 'hard', 'What happens when executing:
```java
ArrayList<String> words = new ArrayList<>();
words.add("A");
words.add("B");
for (String w : words) {
    if (w.equals("A")) words.remove(w);
}
```', '["ConcurrentModificationException is thrown","The element \"A\" is cleanly removed","An IndexOutOfBoundsException is thrown","The loop executes infinitely"]'::jsonb, 'Modifying an `ArrayList` directly (calling `.remove()`) while iterating over it with an enhanced for loop invalidates the underlying iterator, causing a `ConcurrentModificationException`.'),
  ('ap-topic-csa-java_q16', 'ap-topic-csa-java', 16, false, 'A', 'Java Fundamentals & Control Flow', 'medium', 'What is the return value of `"banana".indexOf("an")`?', '["1","2","3","-1"]'::jsonb, '`indexOf` returns the index of the first occurrence of the substring. In `"banana"`, index 0 is ''b'', index 1 is ''a'', index 2 is ''n''. The substring `"an"` starts at index 1.'),
  ('ap-topic-csa-java_q17', 'ap-topic-csa-java', 17, false, 'A', 'Java Fundamentals & Control Flow', 'medium', 'What is the value of `x` after the following code?
```java
int x = 5;
x += x * 2 + 3;
```', '["18","13","25","15"]'::jsonb, 'Due to operator precedence, multiplication occurs first: `x * 2` is $5 \times 2 = 10$. Then $+ 3$ gives 13. Finally, `x += 13` means $x = 5 + 13 = 18$.'),
  ('ap-topic-csa-java_q18', 'ap-topic-csa-java', 18, false, 'A', 'Java Fundamentals & Control Flow', 'hard', 'Consider the method:
```java
public static void alter(int[] nums) {
    nums[0] = 99;
    nums = new int[]{1, 2, 3};
}
```
If `int[] a = {10, 20}; alter(a);`, what is `a[0]` after the method call?', '["99","10","1","20"]'::jsonb, 'Java passes object references by value. `nums[0] = 99;` modifies the contents of the array referred to by `a`. Reassigning `nums = new int[]{...}` merely alters the local parameter copy `nums` to point to a new array, leaving caller''s reference `a` still pointing to the original modified array.'),
  ('ap-topic-csa-java_q19', 'ap-topic-csa-java', 19, false, 'A', 'Java Fundamentals & Control Flow', 'medium', 'Which condition determines if integer `year` is a leap year (divisible by 4 and not by 100, or divisible by 400)?', '["(year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)","year % 4 == 0 || (year % 100 != 0 && year % 400 == 0)","year % 4 == 0 && year % 400 == 0","year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)"]'::jsonb, 'A leap year occurs if the year is divisible by 4 but not by 100, OR if it is divisible by 400. In Java boolean expressions: `(year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)`.'),
  ('ap-topic-csa-java_q20', 'ap-topic-csa-java', 20, false, 'A', 'Java Fundamentals & Control Flow', 'hard', 'How many times is `"AP"` printed?
```java
for (int k = 1; k < 100; k *= 2) {
    System.out.println("AP");
}
```', '["7","6","8","100"]'::jsonb, 'Trace $k$: 1, 2, 4, 8, 16, 32, 64 ($2^0, 2^1, \dots, 2^6$). Next value is 128, which is $\ge 100$. Thus there are 7 iterations (powers of 2 from $2^0$ to $2^6$).'),
  ('ap-topic-csa-oop_q1', 'ap-topic-csa-oop', 1, false, 'B', 'OOP', 'medium', 'Which keyword allows a subclass to invoke a constructor from its superclass?', '["this","super","extends","implements"]'::jsonb, '`super(...)` calls the superclass constructor.'),
  ('ap-topic-csa-oop_q2', 'ap-topic-csa-oop', 2, false, 'A', 'OOP & Inheritance', 'medium', 'Consider classes:
```java
class Vehicle { public void drive() { System.out.print("V"); } }
class Car extends Vehicle { public void drive() { System.out.print("C"); } }
```
What is printed by: `Vehicle myCar = new Car(); myCar.drive();`?', '["C","V","VC","Compilation error"]'::jsonb, 'This illustrates polymorphism and dynamic method lookup (late binding). In Java, non-static method calls are resolved at runtime based on the actual object type (`Car`), not the declared reference type (`Vehicle`). Thus `Car`''s `drive()` method executes, printing "C".'),
  ('ap-topic-csa-oop_q3', 'ap-topic-csa-oop', 3, false, 'A', 'OOP & Inheritance', 'medium', 'Which keyword is used in a subclass constructor to explicitly invoke a constructor of its superclass?', '["super","this","parent","base"]'::jsonb, 'In Java, `super(...)` is used in a subclass constructor to call a superclass constructor. It must be the very first statement in the subclass constructor body.'),
  ('ap-topic-csa-oop_q4', 'ap-topic-csa-oop', 4, false, 'A', 'OOP & Inheritance', 'medium', 'Why should instance variables in a class typically be declared with the `private` access modifier?', '["To encapsulate data and prevent unauthorized external modification","To allow subclasses to access them directly without getter methods","To make the variables accessible to any class in any package","To enable garbage collection to delete them faster"]'::jsonb, 'Declaring instance variables as `private` enforces encapsulation, hiding internal state and requiring external classes to interact through validated accessor (getter) and mutator (setter) methods.'),
  ('ap-topic-csa-oop_q5', 'ap-topic-csa-oop', 5, false, 'A', 'OOP & Inheritance', 'hard', 'Consider classes:
```java
class Person { public String getName() { return "Person"; } }
class Student extends Person { public int getGrade() { return 12; } }
```
Which statement will cause a compile-time error?', '["Person p = new Student(); p.getGrade();","Person p = new Student(); p.getName();","Student s = new Student(); s.getName();","Person p = new Person(); p.getName();"]'::jsonb, 'The compiler checks method validity against the declared reference type. Here `p` has declared type `Person`, and `Person` does not declare a `getGrade()` method. Therefore `p.getGrade()` causes a compile-time error.'),
  ('ap-topic-csa-oop_q6', 'ap-topic-csa-oop', 6, false, 'A', 'OOP & Inheritance', 'medium', 'Which method signature correctly overrides the `equals` method inherited from `java.lang.Object`?', '["public boolean equals(Object obj)","public boolean equals(MyClass obj)","public void equals(Object obj)","public int equals(Object obj)"]'::jsonb, 'To properly override `equals` from `Object`, the method signature must exactly match: `public boolean equals(Object obj)`. Using a specific class parameter overloads rather than overrides.'),
  ('ap-topic-csa-oop_q7', 'ap-topic-csa-oop', 7, false, 'A', 'OOP & Inheritance', 'medium', 'What is true about a class that implements the `Comparable<T>` interface in Java?', '["It must provide an implementation for the `compareTo(T other)` method","It automatically inherits sorting without writing additional code","It cannot have any other interfaces or superclasses","It must declare all instance variables as static"]'::jsonb, 'The `Comparable<T>` interface contains a single method: `int compareTo(T other)`. Any non-abstract class implementing it must implement `compareTo`.'),
  ('ap-topic-csa-oop_q8', 'ap-topic-csa-oop', 8, false, 'A', 'OOP & Inheritance', 'hard', 'Consider the classes:
```java
class Base {
    public Base() { System.out.print("B"); }
}
class Derived extends Base {
    public Derived() { System.out.print("D"); }
}
```
What is printed by: `Derived d = new Derived();`?', '["BD","D","DB","Compilation error"]'::jsonb, 'When a subclass constructor executes without an explicit `super(...)` call, the Java compiler automatically inserts `super();` as the first instruction. Therefore, the superclass `Base` constructor runs first, printing "B", followed by the `Derived` constructor body, printing "D". Output is "BD".'),
  ('ap-topic-csa-oop_q9', 'ap-topic-csa-oop', 9, false, 'A', 'OOP & Inheritance', 'medium', 'What is the key difference between method overloading and method overriding?', '["Overloading uses the same method name with different parameters in the same class; overriding provides a new implementation of an inherited method with the same signature in a subclass","Overloading occurs across subclasses; overriding occurs within a single class","Overloading requires the `super` keyword; overriding requires the `this` keyword","Overloading is decided at runtime; overriding is decided at compile time"]'::jsonb, 'Overloading happens within the same class when methods share the same name but differ in parameter lists. Overriding happens when a subclass replaces an inherited superclass method with identical signature.'),
  ('ap-topic-csa-oop_q10', 'ap-topic-csa-oop', 10, false, 'A', 'OOP & Inheritance', 'hard', 'Consider the class definition:
```java
public class Counter {
    private static int count = 0;
    public Counter() { count++; }
    public static int getCount() { return count; }
}
```
If three `Counter` objects are created, what does `Counter.getCount()` return?', '["3","1","0","NullPointerException"]'::jsonb, 'The `static` modifier means `count` is a class variable shared across all instances of `Counter`. Each constructor invocation increments the single shared `count`, so after 3 objects are instantiated, `count` is 3.'),
  ('ap-topic-csa-oop_q11', 'ap-topic-csa-oop', 11, false, 'A', 'OOP & Inheritance', 'medium', 'Which of the following is true regarding abstract classes in Java?', '["An abstract class cannot be instantiated using the `new` operator","An abstract class cannot contain any concrete methods with bodies","An abstract class cannot declare constructors","A class can extend multiple abstract classes simultaneously"]'::jsonb, 'An abstract class cannot be instantiated directly using `new`; it serves as a base class designed to be extended by concrete subclasses that implement its abstract methods.'),
  ('ap-topic-csa-oop_q12', 'ap-topic-csa-oop', 12, false, 'A', 'OOP & Inheritance', 'medium', 'What is the purpose of the `toString` method in Java?', '["To provide a human-readable String representation of an object''s state","To convert primitive numbers to boolean values","To sort objects in lexicographical order","To compare whether two objects share the same memory location"]'::jsonb, 'The `toString()` method, defined in `Object`, returns a string representation of the object. Overriding it allows developer-friendly inspection of the object''s field values when printed.'),
  ('ap-topic-csa-oop_q13', 'ap-topic-csa-oop', 13, false, 'A', 'OOP & Inheritance', 'hard', 'Consider the class hierarchy: `Animal` -> `Mammal` -> `Dog`. Which of the following assignments is INVALID without an explicit type cast?', '["Dog d = new Mammal();","Animal a = new Dog();","Mammal m = new Dog();","Animal a = new Mammal();"]'::jsonb, 'In Java, upcasting (assigning a subclass reference to a superclass variable) is implicit and automatic. Downcasting (assigning a superclass object to a subclass variable) requires an explicit cast and may throw a `ClassCastException`. Thus `Dog d = new Mammal();` is invalid.'),
  ('ap-topic-csa-oop_q14', 'ap-topic-csa-oop', 14, false, 'A', 'OOP & Inheritance', 'medium', 'When is a default no-argument constructor automatically provided by the Java compiler?', '["Only when no constructors are explicitly declared in the class","Whenever an abstract class is declared","Even when parameterized constructors are explicitly defined","Only when the class implements the `Serializable` interface"]'::jsonb, 'The Java compiler synthesizes a default no-argument constructor if and only if the programmer writes zero constructors in the class. As soon as any constructor is explicitly declared, the default constructor is suppressed.'),
  ('ap-topic-csa-oop_q15', 'ap-topic-csa-oop', 15, false, 'A', 'OOP & Inheritance', 'medium', 'Which statement accurately describes a relationship represented by inheritance versus composition?', '["Inheritance represents an \"is-a\" relationship, whereas composition represents a \"has-a\" relationship","Inheritance represents a \"has-a\" relationship, whereas composition represents an \"is-a\" relationship","Inheritance is achieved through instance variables; composition is achieved with the `extends` keyword","Both inheritance and composition require the `implements` keyword"]'::jsonb, 'Inheritance models an "is-a" taxonomy (e.g., Dog is a Mammal). Composition models a "has-a" structure where an object holds references to other objects (e.g., Car has an Engine).'),
  ('ap-topic-csa-oop_q16', 'ap-topic-csa-oop', 16, false, 'A', 'OOP & Inheritance', 'hard', 'Consider:
```java
public class Test {
    private int val;
    public Test(int val) { this.val = val; }
    public boolean equals(Object other) {
        if (other instanceof Test) {
            return this.val == ((Test) other).val;
        }
        return false;
    }
}
```
What will `new Test(5).equals(new Test(5))` return?', '["true","false","Compilation error","ClassCastException"]'::jsonb, 'The `equals` method checks `other instanceof Test` (which is true), safely casts `(Test) other`, and compares `this.val == ((Test) other).val`, which evaluates $5 == 5$ (true).'),
  ('ap-topic-csa-oop_q17', 'ap-topic-csa-oop', 17, false, 'A', 'OOP & Inheritance', 'medium', 'What happens if a method declared in an interface is NOT implemented in a concrete class that implements that interface?', '["A compile-time error occurs","A runtime `NoSuchMethodError` occurs","The method defaults to returning null or 0","The interface method is ignored"]'::jsonb, 'A concrete class must provide implementations for all abstract methods declared in implemented interfaces; failure to do so produces a compilation error.'),
  ('ap-topic-csa-oop_q18', 'ap-topic-csa-oop', 18, false, 'A', 'OOP & Inheritance', 'medium', 'Which of the following describes the purpose of the `final` keyword when applied to a class?', '["The class cannot be extended by any subclass","All methods in the class are automatically executed once","The class cannot declare any methods","The class variables can never be read"]'::jsonb, 'Applying `final` to a class declaration prevents any other class from inheriting from it (e.g., `java.lang.String` is a final class).'),
  ('ap-topic-csa-oop_q19', 'ap-topic-csa-oop', 19, false, 'A', 'OOP & Inheritance', 'hard', 'Consider:
```java
class Alpha { public void show() { System.out.print("A"); } }
class Beta extends Alpha { public void show() { super.show(); System.out.print("B"); } }
class Gamma extends Beta { public void show() { super.show(); System.out.print("G"); } }
```
What is printed by: `Alpha obj = new Gamma(); obj.show();`?', '["ABG","G","GBA","BAG"]'::jsonb, 'Dynamic binding calls `Gamma.show()`. Inside `Gamma.show()`, `super.show()` calls `Beta.show()`. Inside `Beta.show()`, `super.show()` calls `Alpha.show()`, which prints "A". Then `Beta.show()` resumes, printing "B". Finally `Gamma.show()` finishes by printing "G". Output is "ABG".'),
  ('ap-topic-csa-oop_q20', 'ap-topic-csa-oop', 20, false, 'A', 'OOP & Inheritance', 'medium', 'Which method call represents legal auto-boxing in Java?', '["Integer x = 42;","int x = new Double(4.2);","String s = 100;","boolean b = \"true\";"]'::jsonb, 'Autoboxing is the automatic conversion that the Java compiler makes between primitive types and their corresponding object wrapper classes (e.g., converting primitive `int 42` into `Integer.valueOf(42)`).')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-csp-cyber_q1', 'ap-topic-csp-cyber', 1, false, 'B', 'Networks', 'easy', 'Which protocol ensures secure, encrypted communication over the internet?', '["HTTP","HTTPS","FTP","IP"]'::jsonb, 'HTTPS encrypts communications using SSL/TLS.'),
  ('ap-topic-csp-cyber_q2', 'ap-topic-csp-cyber', 2, false, 'A', 'Cybersecurity & Networks', 'medium', 'How does public key (asymmetric) cryptography differ fundamentally from symmetric encryption?', '["Asymmetric encryption uses a mathematically paired public key for encryption and private key for decryption, whereas symmetric encryption uses a single shared secret key for both","Asymmetric encryption cannot be used over the Internet, whereas symmetric encryption is Internet-native","Asymmetric encryption only encrypts integer data, whereas symmetric encryption encrypts strings","Asymmetric encryption does not require any mathematical algorithms"]'::jsonb, 'Symmetric encryption uses the same shared key to encrypt and decrypt data. Asymmetric (public key) encryption uses a key pair: anyone can encrypt using the recipient''s public key, but only the recipient''s private key can decrypt it.'),
  ('ap-topic-csp-cyber_q3', 'ap-topic-csp-cyber', 3, false, 'A', 'Cybersecurity & Networks', 'medium', 'What is the primary role of a Certificate Authority (CA) in secure web communications (HTTPS)?', '["To verify the identity of a website and digitally sign its public key certificate","To block incoming denial-of-service traffic from distributed botnets","To store user passwords in plaintext for recovery services","To convert IP addresses into human-readable domain names"]'::jsonb, 'A Certificate Authority (CA) is a trusted third-party entity that validates the identity of organizations and issues digital certificates binding their domain to their public key.'),
  ('ap-topic-csp-cyber_q4', 'ap-topic-csp-cyber', 4, false, 'A', 'Cybersecurity & Networks', 'medium', 'What type of attack involves overwhelming an online service with malicious traffic originating from thousands of compromised IoT devices (a botnet)?', '["Distributed Denial of Service (DDoS)","Phishing attack","SQL Injection","Man-in-the-Middle (MitM) eavesdropping"]'::jsonb, 'A Distributed Denial of Service (DDoS) attack harnesses multiple distributed systems (a botnet) to flood bandwidth or system resources of a targeted server until it cannot respond to legitimate users.'),
  ('ap-topic-csp-cyber_q5', 'ap-topic-csp-cyber', 5, false, 'A', 'Cybersecurity & Networks', 'medium', 'Which scenario best exemplifies a multi-factor authentication (MFA) system?', '["Entering a master password and then inputting a one-time passcode sent to a smartphone","Entering a password and then entering a backup password stored on the same device","Entering a username and answering two security questions","Entering a password followed by typing an email address"]'::jsonb, 'MFA requires credentials from at least two different factor categories: something you know (password), something you have (phone/token), or something you are (biometrics). A password plus a one-time code combines knowledge and possession.'),
  ('ap-topic-csp-cyber_q6', 'ap-topic-csp-cyber', 6, false, 'A', 'Cybersecurity & Networks', 'medium', 'What is the primary function of the Domain Name System (DNS)?', '["Translating human-readable domain names (like example.com) into numerical IP addresses","Routing packets between intermediate autonomous systems","Encrypting web traffic between client browsers and servers","Assigning MAC addresses to physical network interfaces"]'::jsonb, 'DNS acts as the phonebook of the Internet, translating user-friendly domain names (e.g. `example.com`) into computer-routable IP addresses (e.g. `93.184.216.34`).'),
  ('ap-topic-csp-cyber_q7', 'ap-topic-csp-cyber', 7, false, 'A', 'Cybersecurity & Networks', 'hard', 'How does IPv6 solve the primary limitation of IPv4?', '["IPv6 uses 128-bit addresses, vastly expanding the available address space compared to IPv4''s 32-bit addresses","IPv6 removes the need for routers on the Internet","IPv6 makes all network communications automatically unhackable without encryption","IPv6 increases physical copper wire transmission speeds tenfold"]'::jsonb, 'IPv4 uses 32-bit addresses ($2^{32} \approx 4.3$ billion addresses), which has been depleted. IPv6 uses 128-bit addresses ($2^{128} \approx 3.4 \times 10^{38}$ addresses), providing a virtually inexhaustible address pool.'),
  ('ap-topic-csp-cyber_q8', 'ap-topic-csp-cyber', 8, false, 'A', 'Cybersecurity & Networks', 'medium', 'In computer networking, what makes packet switching resilient and fault-tolerant?', '["Packets can be independently routed along dynamic paths around network congestion or link failures","All packets are required to travel along a single dedicated copper wire reserved for the session","If any single intermediate router fails, the entire Internet automatically reboots","Packets travel without headers or destination addresses"]'::jsonb, 'In packet switching, data is broken into discrete packets that navigate independently. Routers inspect headers and dynamically steer packets around congested or severed lines, ensuring network redundancy.'),
  ('ap-topic-csp-cyber_q9', 'ap-topic-csp-cyber', 9, false, 'A', 'Cybersecurity & Networks', 'medium', 'Which social engineering attack tricks victims into revealing sensitive information through deceptive emails disguised as trusted institutions?', '["Phishing","Trojan horse injection","Buffer overflow","Ransomware deployment"]'::jsonb, 'Phishing is a deceptive communication technique where an attacker masquerades as a trustworthy entity (e.g., bank, school admin) to lure victims into revealing credentials or financial data.'),
  ('ap-topic-csp-cyber_q10', 'ap-topic-csp-cyber', 10, false, 'A', 'Cybersecurity & Networks', 'hard', 'Why is Transmission Control Protocol (TCP) considered a "reliable" transport protocol compared to User Datagram Protocol (UDP)?', '["TCP establishes connections, verifies packet receipt with ACKs, and retransmits lost packets in order","TCP transmits packets twice as fast as UDP without error checking","TCP encrypts data at the physical layer","TCP allows data transmission without IP addresses"]'::jsonb, 'TCP guarantees orderly and error-checked delivery of packets through sequence numbers, acknowledgments (ACKs), and automatic retransmission of lost packets. UDP is connectionless and does not guarantee delivery.'),
  ('ap-topic-csp-cyber_q11', 'ap-topic-csp-cyber', 11, false, 'A', 'Cybersecurity & Networks', 'medium', 'What is the purpose of a cryptographic hash function (such as SHA-256) in data integrity verification?', '["It produces a unique fixed-length digest such that even a tiny change to the input completely alters the output hash","It compresses large video files into zip archives without data loss","It reverses any encrypted ciphertext back into original plaintext without a key","It generates random IP addresses for home routers"]'::jsonb, 'A cryptographic hash function is a one-way deterministic algorithm producing a fixed-size digest. The avalanche effect ensures that altering even one bit in the input produces a dramatically different hash, verifying data integrity.'),
  ('ap-topic-csp-cyber_q12', 'ap-topic-csp-cyber', 12, false, 'A', 'Cybersecurity & Networks', 'medium', 'What security threat is created when an application allows user input to be directly embedded into a database query without sanitization?', '["SQL Injection (SQLi)","DNS spoofing","Cross-Site Request Forgery (CSRF)","Zero-day hardware vulnerability"]'::jsonb, 'SQL Injection occurs when malicious SQL statements are inserted into entry fields and executed by the backend database, potentially allowing unauthorized data extraction, modification, or deletion.'),
  ('ap-topic-csp-cyber_q13', 'ap-topic-csp-cyber', 13, false, 'A', 'Cybersecurity & Networks', 'medium', 'What is the "digital divide" in computer science principles?', '["The socioeconomic and geographic disparity in access to digital technologies and high-speed internet","The architectural difference between 32-bit and 64-bit processors","The mathematical division remainder operator in programming languages","The separation between client frontend code and server backend databases"]'::jsonb, 'The digital divide refers to inequality regarding access to information and communication technologies (computers, broadband internet, digital literacy) based on socioeconomic, ethnic, or geographic factors.'),
  ('ap-topic-csp-cyber_q14', 'ap-topic-csp-cyber', 14, false, 'A', 'Cybersecurity & Networks', 'hard', 'How does HTTPS secure web communication compared to plain HTTP?', '["HTTPS uses TLS/SSL to encrypt HTTP requests and responses, ensuring confidentiality and integrity","HTTPS replaces IP routing with satellite broadcasting","HTTPS prevents websites from storing user cookies","HTTPS makes websites immune to web server hardware crashes"]'::jsonb, 'HTTPS (Hypertext Transfer Protocol Secure) layers HTTP over Transport Layer Security (TLS/SSL), providing symmetric session encryption, cryptographic integrity verification, and server authentication.'),
  ('ap-topic-csp-cyber_q15', 'ap-topic-csp-cyber', 15, false, 'A', 'Cybersecurity & Networks', 'medium', 'What is a "zero-day vulnerability"?', '["A software security flaw unknown to the vendor, for which zero days have passed since discovery and no patch exists","A bug that automatically fixes itself within 24 hours","A computer clock synchronization failure occurring at midnight","A virus that erases hard drives after zero days of installation"]'::jsonb, 'A zero-day vulnerability is a flaw unknown to the software creator or public, leaving systems defenseless because developers have had "zero days" to engineer and release a security patch.'),
  ('ap-topic-csp-cyber_q16', 'ap-topic-csp-cyber', 16, false, 'A', 'Cybersecurity & Networks', 'medium', 'Which of the following is considered Personally Identifiable Information (PII)?', '["Social Security number and home address","The current weather forecast of a state","A website''s public favicon image","The open-source license text of a software package"]'::jsonb, 'Personally Identifiable Information (PII) is any data that could potentially identify a specific individual, such as Social Security number, home address, biometric records, or passport number.'),
  ('ap-topic-csp-cyber_q17', 'ap-topic-csp-cyber', 17, false, 'A', 'Cybersecurity & Networks', 'hard', 'In a Man-in-the-Middle (MitM) attack over an unsecured public Wi-Fi network, what does the attacker do?', '["Intercepts and potentially alters communication packets passing between the user and the router","Physically takes control of the user''s laptop keyboard","Guesses the user''s password using a rainbow table dictionary offline","Disassembles the cellular transmission tower"]'::jsonb, 'In a MitM attack, the attacker secretly positions themselves between two communicating parties, intercepting, reading, and potentially tampering with transmissions in transit without either party knowing.'),
  ('ap-topic-csp-cyber_q18', 'ap-topic-csp-cyber', 18, false, 'A', 'Cybersecurity & Networks', 'medium', 'What is the primary function of a network firewall?', '["To monitor and filter incoming and outgoing network traffic based on predetermined security rules","To physically protect server room cables from electrical overheating","To provide backup battery power during an electrical grid failure","To compress email attachments automatically"]'::jsonb, 'A firewall acts as a security gateway between internal private networks and external untrusted networks, inspecting packets and enforcing rules to block unauthorized traffic.'),
  ('ap-topic-csp-cyber_q19', 'ap-topic-csp-cyber', 19, false, 'A', 'Cybersecurity & Networks', 'hard', 'Why is bandwidth measured in bits per second (bps) rather than bytes per second (Bps)?', '["Networking hardware transmits data serially as individual electrical or optical bits along physical channels","Bytes cannot be transmitted over radio waves","A byte has no standardized definition in computer science","Bits are only used for software while bytes are only used for hardware"]'::jsonb, 'Network transmission channels convey signals one bit at a time (serially). Network throughput and capacity are therefore standardized in bits per second (e.g., Mbps, Gbps).'),
  ('ap-topic-csp-cyber_q20', 'ap-topic-csp-cyber', 20, false, 'A', 'Cybersecurity & Networks', 'medium', 'What type of malicious software encrypts a victim''s files and demands financial payment in exchange for the decryption key?', '["Ransomware","Spyware","Adware","Worm"]'::jsonb, 'Ransomware is malware that utilizes strong encryption to lock files on a victim''s system, demanding payment (often in cryptocurrency) before supplying the decryption key.'),
  ('ap-topic-precalc-trig_q1', 'ap-topic-precalc-trig', 1, false, 'B', 'Trigonometry', 'easy', 'Find the period of $f(x) = \sin(3x)$.', '["$\\pi/3$","\\$2\\pi/3$","$\\pi$","\\$2\\pi$"]'::jsonb, 'Period formula $T = 2\pi / b = 2\pi/3$.'),
  ('ap-topic-precalc-trig_q2', 'ap-topic-precalc-trig', 2, false, 'A', 'Polynomial & Trigonometric Models', 'medium', 'What is the period and amplitude of the sinusoidal function $f(x) = -4 \cos\left(\frac{\pi}{3} x + \frac{\pi}{2}\right) + 7$?', '["Period: 6, Amplitude: 4","Period: $2\\pi/3$, Amplitude: -4","Period: 6, Amplitude: 7","Period: 3, Amplitude: 4"]'::jsonb, 'For $f(x) = A \cos(Bx + C) + D$: Amplitude is $|A| = |-4| = 4$. The coefficient $B = \frac{\pi}{3}$, so the period is $T = \frac{2\pi}{B} = \frac{2\pi}{\pi/3} = 6$.'),
  ('ap-topic-precalc-trig_q3', 'ap-topic-precalc-trig', 3, false, 'A', 'Polynomial & Trigonometric Models', 'medium', 'Find the exact value of $\sin\left(\frac{11\pi}{6}\right)$.', '["-1/2","1/2","$-\\sqrt{3}/2$","$\\sqrt{3}/2$"]'::jsonb, '$\frac{11\pi}{6}$ is in Quadrant IV with reference angle $\frac{\pi}{6}$. Since sine is negative in Quadrant IV, $\sin(11\pi/6) = -\sin(\pi/6) = -\frac{1}{2}$.'),
  ('ap-topic-precalc-trig_q4', 'ap-topic-precalc-trig', 4, false, 'A', 'Polynomial & Trigonometric Models', 'medium', 'Convert the rectangular coordinates $(-3, 3\sqrt{3})$ to polar coordinates $(r, \theta)$ with $r > 0$ and $0 \le \theta < 2\pi$.', '["$(6, 2\\pi/3)$","$(6, 5\\pi/6)$","$(6, \\pi/3)$","$(12, 2\\pi/3)$"]'::jsonb, '$r = \sqrt{(-3)^2 + (3\sqrt{3})^2} = \sqrt{9 + 27} = \sqrt{36} = 6$. Since $x = -3 < 0$ and $y = 3\sqrt{3} > 0$, the point lies in Quadrant II. $\tan\theta = \frac{y}{x} = \frac{3\sqrt{3}}{-3} = -\sqrt{3}$. Thus $\theta = \pi - \frac{\pi}{3} = \frac{2\pi}{3}$. The polar coordinate is $(6, 2\pi/3)$.'),
  ('ap-topic-precalc-trig_q5', 'ap-topic-precalc-trig', 5, false, 'A', 'Polynomial & Trigonometric Models', 'hard', 'Solve the equation $2\cos^2\theta - \cos\theta - 1 = 0$ for $0 \le \theta < 2\pi$.', '["$0, \\frac{2\\pi}{3}, \\frac{4\\pi}{3}$","$\\frac{\\pi}{3}, \\pi, \\frac{5\\pi}{3}$","$\\frac{\\pi}{2}, \\frac{3\\pi}{2}, \\pi$","$0, \\frac{\\pi}{3}, \\frac{5\\pi}{3}$"]'::jsonb, 'Factor as quadratic in $\cos\theta$: $(2\cos\theta + 1)(\cos\theta - 1) = 0$. Case 1: $\cos\theta = 1 \implies \theta = 0$. Case 2: $\cos\theta = -\frac{1}{2} \implies \theta = \frac{2\pi}{3}$ and $\theta = \frac{4\pi}{3}$. Solutions: $0, \frac{2\pi}{3}, \frac{4\pi}{3}$.'),
  ('ap-topic-precalc-trig_q6', 'ap-topic-precalc-trig', 6, false, 'A', 'Polynomial & Trigonometric Models', 'medium', 'Evaluate $\cos(\alpha + \beta)$ given that $\sin\alpha = \frac{3}{5}$ with $\alpha$ in Quadrant I, and $\cos\beta = -\frac{5}{13}$ with $\beta$ in Quadrant II.', '["-56/65","-16/65","56/65","16/65"]'::jsonb, 'For $\alpha$ in Q1: $\cos\alpha = \sqrt{1 - (3/5)^2} = \frac{4}{5}$. For $\beta$ in Q2: $\sin\beta = \sqrt{1 - (-5/13)^2} = \frac{12}{13}$. Using cosine sum formula $\cos(\alpha + \beta) = \cos\alpha\cos\beta - \sin\alpha\sin\beta$: $\cos(\alpha + \beta) = \left(\frac{4}{5}\right)\left(-\frac{5}{13}\right) - \left(\frac{3}{5}\right)\left(\frac{12}{13}\right) = -\frac{20}{65} - \frac{36}{65} = -\frac{56}{65}$.'),
  ('ap-topic-precalc-trig_q7', 'ap-topic-precalc-trig', 7, false, 'A', 'Polynomial & Trigonometric Models', 'medium', 'Find all vertical asymptotes of the rational function $R(x) = \frac{x^2 - 4}{x^2 - 5x + 6}$.', '["$x = 3$ only","$x = 2$ and $x = 3$","$x = 2$ only","$x = -2$ and $x = 3$"]'::jsonb, 'Factor numerator and denominator: $R(x) = \frac{(x - 2)(x + 2)}{(x - 2)(x - 3)}$. The factor $(x - 2)$ cancels, creating a removable discontinuity (hole) at $x = 2$. The remaining denominator factor $(x - 3)$ creates a vertical asymptote at $x = 3$.'),
  ('ap-topic-precalc-trig_q8', 'ap-topic-precalc-trig', 8, false, 'A', 'Polynomial & Trigonometric Models', 'hard', 'Solve for $x$: $\log_2(x + 3) + \log_2(x - 1) = 5$.', '["5","5 and -7","7","4"]'::jsonb, 'Use log product property: $\log_2((x + 3)(x - 1)) = 5 \implies (x + 3)(x - 1) = 2^5 = 32$. Expanding: $x^2 + 2x - 3 = 32 \implies x^2 + 2x - 35 = 0 \implies (x + 7)(x - 5) = 0$. Since logarithms require positive arguments ($x > 1$), $x = -7$ is extraneous. Thus, $x = 5$.'),
  ('ap-topic-precalc-trig_q9', 'ap-topic-precalc-trig', 9, false, 'A', 'Polynomial & Trigonometric Models', 'medium', 'Evaluate $\arcsin\left(\sin\left(\frac{5\pi}{6}\right)\right)$.', '["$\\pi/6$","$5\\pi/6$","$-\\pi/6$","$7\\pi/6$"]'::jsonb, 'First evaluate inside: $\sin(5\pi/6) = \frac{1}{2}$. The range of the principal $\arcsin$ function is $\left[-\frac{\pi}{2}, \frac{\pi}{2}\right]$. The unique angle in this range whose sine is $\frac{1}{2}$ is $\frac{\pi}{6}$.'),
  ('ap-topic-precalc-trig_q10', 'ap-topic-precalc-trig', 10, false, 'A', 'Polynomial & Trigonometric Models', 'medium', 'What is the end behavior of the polynomial $P(x) = -2x^5 + 7x^3 - 4x + 9$?', '["As $x \\to \\infty$, $P(x) \\to -\\infty$; as $x \\to -\\infty$, $P(x) \\to \\infty$","As $x \\to \\infty$, $P(x) \\to \\infty$; as $x \\to -\\infty$, $P(x) \\to -\\infty$","As $x \\to \\pm\\infty$, $P(x) \\to -\\infty$","As $x \\to \\pm\\infty$, $P(x) \\to \\infty$"]'::jsonb, 'Leading term is $-2x^5$. The degree is odd (5) and the leading coefficient is negative (-2). As $x \to \infty$, $(-2)(+\infty) \to -\infty$. As $x \to -\infty$, $(-2)(-\infty) \to \infty$.'),
  ('ap-topic-precalc-trig_q11', 'ap-topic-precalc-trig', 11, false, 'A', 'Polynomial & Trigonometric Models', 'medium', 'Which expression is identical to $\frac{1}{1 - \cos x} + \frac{1}{1 + \cos x}$?', '["$2\\csc^2 x$","$2\\sec^2 x$","$2\\sin^2 x$","$\\cot^2 x$"]'::jsonb, 'Combine fractions with common denominator: $\frac{(1 + \cos x) + (1 - \cos x)}{(1 - \cos x)(1 + \cos x)} = \frac{2}{1 - \cos^2 x} = \frac{2}{\sin^2 x} = 2\csc^2 x$.'),
  ('ap-topic-precalc-trig_q12', 'ap-topic-precalc-trig', 12, false, 'A', 'Polynomial & Trigonometric Models', 'hard', 'A Ferris wheel with diameter 60 feet rotates at a constant rate, completing one revolution every 40 seconds. Passengers board at the lowest point, 4 feet above the ground, at $t = 0$. Which function models passenger height $h(t)$ in feet?', '["$h(t) = -30\\cos\\left(\\frac{\\pi}{20} t\\right) + 34$","$h(t) = 30\\cos\\left(\\frac{\\pi}{20} t\\right) + 34$","$h(t) = -60\\cos\\left(\\frac{\\pi}{40} t\\right) + 4$","$h(t) = -30\\sin\\left(\\frac{\\pi}{20} t\\right) + 34$"]'::jsonb, 'Radius (amplitude) is $60/2 = 30\text{ ft}$. Lowest height is 4 ft, highest is $4 + 60 = 64\text{ ft}$. Midline is $\frac{64 + 4}{2} = 34\text{ ft}$. Period is $40\text{ s}$, so $B = \frac{2\pi}{40} = \frac{\pi}{20}$. Starting at the minimum at $t = 0$ corresponds to a negative cosine curve: $h(t) = -30\cos\left(\frac{\pi}{20} t\right) + 34$.'),
  ('ap-topic-precalc-trig_q13', 'ap-topic-precalc-trig', 13, false, 'A', 'Polynomial & Trigonometric Models', 'medium', 'Solve for all solutions of $e^{2x} - 5e^x + 6 = 0$.', '["$x = \\ln 2$ and $x = \\ln 3$","$x = 2$ and $x = 3$","$x = e^2$ and $x = e^3$","$x = \\ln 5$ and $x = \\ln 6$"]'::jsonb, 'Let $u = e^x$. The equation becomes $u^2 - 5u + 6 = 0 \implies (u - 2)(u - 3) = 0 \implies u = 2$ or $u = 3$. Back-substituting $e^x$: $e^x = 2 \implies x = \ln 2$; $e^x = 3 \implies x = \ln 3$.'),
  ('ap-topic-precalc-trig_q14', 'ap-topic-precalc-trig', 14, false, 'A', 'Polynomial & Trigonometric Models', 'hard', 'What is the exact value of $\tan(2\theta)$ if $\sin\theta = \frac{4}{5}$ and $\theta$ is in Quadrant II?', '["24/7","-24/7","7/24","-7/24"]'::jsonb, 'In Q2, $\cos\theta = -\sqrt{1 - (4/5)^2} = -\frac{3}{5}$. Thus $\tan\theta = \frac{\sin\theta}{\cos\theta} = \frac{4/5}{-3/5} = -\frac{4}{3}$. Use double-angle identity: $\tan(2\theta) = \frac{2\tan\theta}{1 - \tan^2\theta} = \frac{2(-4/3)}{1 - (-4/3)^2} = \frac{-8/3}{1 - 16/9} = \frac{-8/3}{-7/9} = \left(-\frac{8}{3}\right)\left(-\frac{9}{7}\right) = \frac{24}{7}$.'),
  ('ap-topic-precalc-trig_q15', 'ap-topic-precalc-trig', 15, false, 'A', 'Polynomial & Trigonometric Models', 'medium', 'Find the slant (oblique) asymptote of $f(x) = \frac{2x^2 + 5x - 1}{x + 2}$.', '["$y = 2x + 1$","$y = 2x - 1$","$y = 2x + 5$","$y = x + 2$"]'::jsonb, 'Perform polynomial long division: $(2x^2 + 5x - 1) \div (x + 2) = 2x + 1 + \frac{-3}{x + 2}$. As $x \to \pm\infty$, $\frac{-3}{x + 2} \to 0$, so the slant asymptote is $y = 2x + 1$.'),
  ('ap-topic-precalc-trig_q16', 'ap-topic-precalc-trig', 16, false, 'A', 'Polynomial & Trigonometric Models', 'medium', 'What is the sum of the zeros of $f(x) = 3x^3 - 9x^2 + 4x - 12$?', '["3","-3","4/3","12"]'::jsonb, 'By Vieta''s formulas, for a cubic $ax^3 + bx^2 + cx + d = 0$, the sum of the zeros is $-\frac{b}{a}$. Here $a = 3$ and $b = -9$, so sum $= -\frac{-9}{3} = 3$.'),
  ('ap-topic-precalc-trig_q17', 'ap-topic-precalc-trig', 17, false, 'A', 'Polynomial & Trigonometric Models', 'hard', 'Convert the polar equation $r = 4\cos\theta$ into an equivalent Cartesian equation.', '["$(x - 2)^2 + y^2 = 4$","$x^2 + (y - 2)^2 = 4$","$x^2 + y^2 = 16$","$(x - 4)^2 + y^2 = 16$"]'::jsonb, 'Multiply both sides by $r$: $r^2 = 4r\cos\theta$. Substitute $r^2 = x^2 + y^2$ and $r\cos\theta = x$: $x^2 + y^2 = 4x$. Rearrange and complete the square: $x^2 - 4x + 4 + y^2 = 4 \implies (x - 2)^2 + y^2 = 4$. This is a circle of radius 2 centered at $(2, 0)$.'),
  ('ap-topic-precalc-trig_q18', 'ap-topic-precalc-trig', 18, false, 'A', 'Polynomial & Trigonometric Models', 'medium', 'Find the domain of the function $f(x) = \sqrt{\ln(x - 2)}$.', '["$[3, \\infty)$","$(2, \\infty)$","$[2, \\infty)$","$(3, \\infty)$"]'::jsonb, 'For the square root, the argument must be non-negative: $\ln(x - 2) \ge 0 \implies x - 2 \ge e^0 = 1 \implies x \ge 3$. This also automatically satisfies the log domain restriction $x - 2 > 0$. Thus the domain is $[3, \infty)$.'),
  ('ap-topic-precalc-trig_q19', 'ap-topic-precalc-trig', 19, false, 'A', 'Polynomial & Trigonometric Models', 'hard', 'What is the exact value of $\sin(15^\circ)$?', '["$\\frac{\\sqrt{6} - \\sqrt{2}}{4}$","$\\frac{\\sqrt{6} + \\sqrt{2}}{4}$","$\\frac{\\sqrt{3} - 1}{2}$","$\\frac{\\sqrt{2} - 1}{2}$"]'::jsonb, 'Use the difference formula $\sin(45^\circ - 30^\circ) = \sin 45^\circ\cos 30^\circ - \cos 45^\circ\sin 30^\circ = \left(\frac{\sqrt{2}}{2}\right)\left(\frac{\sqrt{3}}{2}\right) - \left(\frac{\sqrt{2}}{2}\right)\left(\frac{1}{2}\right) = \frac{\sqrt{6} - \sqrt{2}}{4}$.'),
  ('ap-topic-precalc-trig_q20', 'ap-topic-precalc-trig', 20, false, 'A', 'Polynomial & Trigonometric Models', 'medium', 'Which function is strictly increasing on its entire natural domain?', '["$f(x) = 2^x$","$g(x) = \\cos x$","$h(x) = x^2$","$k(x) = \\frac{1}{x}$"]'::jsonb, 'An exponential function $b^x$ with base $b > 1$ has positive derivative $\frac{d}{dx}[2^x] = 2^x \ln 2 > 0$ for all $x \in \mathbb{R}$, so it is strictly increasing everywhere.'),
  ('ap-topic-stats-data_q1', 'ap-topic-stats-data', 1, false, 'B', 'Probability', 'medium', 'If events A and B are independent with P(A) = 0.4 and P(B) = 0.5, what is P(A and B)?', '["0.1","0.2","0.9","0.45"]'::jsonb, 'For independent events: $P(A \cap B) = P(A) \times P(B) = 0.4 \times 0.5 = 0.2$.'),
  ('ap-topic-stats-data_q2', 'ap-topic-stats-data', 2, false, 'A', 'Exploring Data & Probability', 'medium', 'A dataset has $Q_1 = 24$ and $Q_3 = 40$. According to the standard $1.5 \times \text{IQR}$ outlier rule, any observation below what cutoff is an outlier?', '["0","8","16","24"]'::jsonb, '$\text{IQR} = Q_3 - Q_1 = 40 - 24 = 16$. Lower outlier threshold $= Q_1 - 1.5 \times \text{IQR} = 24 - 1.5(16) = 24 - 24 = 0$.'),
  ('ap-topic-stats-data_q3', 'ap-topic-stats-data', 3, false, 'A', 'Exploring Data & Probability', 'medium', 'In a strongly right-skewed distribution of household incomes, what is the expected relationship between the mean and the median?', '["The mean is greater than the median","The mean is equal to the median","The mean is less than the median","The relationship cannot be predicted"]'::jsonb, 'Extreme high income values in the right tail pull the non-resistant mean upward, whereas the resistant median remains relatively unaffected. Therefore, in a right-skewed distribution, $\text{mean} > \text{median}$.'),
  ('ap-topic-stats-data_q4', 'ap-topic-stats-data', 4, false, 'A', 'Exploring Data & Probability', 'medium', 'Exam scores are normally distributed with mean $\mu = 72$ and standard deviation $\sigma = 8$. Approximately what percentage of students scored between 64 and 88?', '["81.5%","68%","95%","84%"]'::jsonb, 'Using standard deviations: $64 = \mu - 1\sigma$ and $88 = \mu + 2\sigma$. By the 68-95-99.7 Empirical Rule, the interval from $-1\sigma$ to $+1\sigma$ contains $68\%$, and from $+1\sigma$ to $+2\sigma$ contains $\frac{95\% - 68\%}{2} = 13.5\%$. Total percentage between $-1\sigma$ and $+2\sigma$ is $68\% + 13.5\% = 81.5\%$.'),
  ('ap-topic-stats-data_q5', 'ap-topic-stats-data', 5, false, 'A', 'Exploring Data & Probability', 'medium', 'If events $A$ and $B$ are independent with $P(A) = 0.4$ and $P(B) = 0.5$, what is $P(A \cup B)$?', '["0.70","0.90","0.20","0.60"]'::jsonb, 'By independence, $P(A \cap B) = P(A)P(B) = 0.4 \times 0.5 = 0.20$. By the addition rule: $P(A \cup B) = P(A) + P(B) - P(A \cap B) = 0.4 + 0.5 - 0.20 = 0.70$.'),
  ('ap-topic-stats-data_q6', 'ap-topic-stats-data', 6, false, 'A', 'Exploring Data & Probability', 'hard', 'A linear regression model produces $r = -0.80$. What percentage of the variation in the response variable is explained by the linear relationship with the explanatory variable?', '["64%","80%","-80%","36%"]'::jsonb, 'The proportion of variation explained by linear regression is given by the coefficient of determination $r^2 = (-0.80)^2 = 0.64$, or $64\%$.'),
  ('ap-topic-stats-data_q7', 'ap-topic-stats-data', 7, false, 'A', 'Exploring Data & Probability', 'medium', 'What is the primary indicator on a residual plot that a linear regression model is appropriate?', '["A random scatter of points with no discernible pattern around the horizontal zero line","A distinct curved U-shaped pattern across the plot","All residuals strictly positive above the zero line","A strong linear trend sloping from bottom-left to top-right"]'::jsonb, 'A random scatter of residual points with uniform variance and no curve confirms that a linear model appropriately captures the relationship without missing non-linear trends.'),
  ('ap-topic-stats-data_q8', 'ap-topic-stats-data', 8, false, 'A', 'Exploring Data & Probability', 'medium', 'In a random sample of 100 students, 60 favor a new policy. What is the standard error of the sample proportion $\hat{p}$?', '["0.049","0.0024","0.49","0.024"]'::jsonb, '$\hat{p} = \frac{60}{100} = 0.60$. The standard error is $\text{SE}(\hat{p}) = \sqrt{\frac{\hat{p}(1 - \hat{p})}{n}} = \sqrt{\frac{0.60(0.40)}{100}} = \sqrt{\frac{0.24}{100}} = \sqrt{0.0024} \approx 0.04899 \approx 0.049$.'),
  ('ap-topic-stats-data_q9', 'ap-topic-stats-data', 9, false, 'A', 'Exploring Data & Probability', 'hard', 'What happens to the width of a confidence interval for a population mean when the sample size $n$ is quadrupled, assuming confidence level and standard deviation remain constant?', '["The width is halved (reduced by a factor of 2)","The width is reduced by a factor of 4","The width is doubled","The width remains unchanged"]'::jsonb, 'Margin of error is $E = z^* \frac{\sigma}{\sqrt{n}}$. If $n$ becomes $4n$, the new margin of error is $z^* \frac{\sigma}{\sqrt{4n}} = \frac{1}{2} \left(z^* \frac{\sigma}{\sqrt{n}}\right)$. Thus, the width is halved.'),
  ('ap-topic-stats-data_q10', 'ap-topic-stats-data', 10, false, 'A', 'Exploring Data & Probability', 'medium', 'In hypothesis testing, what is a Type I error?', '["Rejecting a true null hypothesis ($H_0$ is true, but rejected)","Failing to reject a false null hypothesis ($H_0$ is false, but not rejected)","Calculating an incorrect standard error formula","Choosing an unrepresentative sample"]'::jsonb, 'A Type I error (false positive) occurs when the null hypothesis $H_0$ is actually true, but the researcher erroneously rejects it. The probability of this error is the significance level $\alpha$.')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-stats-data_q11', 'ap-topic-stats-data', 11, false, 'A', 'Exploring Data & Probability', 'medium', 'A fair six-sided die is rolled 5 times. What is the probability of rolling exactly two 4s?', '["$\\binom{5}{2} (1/6)^2 (5/6)^3$","$(1/6)^2 (5/6)^3$","$\\binom{5}{2} (1/6)^3 (5/6)^2$","$(1/6)^2$"]'::jsonb, 'By the binomial probability formula $P(X = k) = \binom{n}{k} p^k (1 - p)^{n - k}$ with $n = 5$, $k = 2$, and $p = 1/6$: $P(X = 2) = \binom{5}{2} (1/6)^2 (5/6)^3$.'),
  ('ap-topic-stats-data_q12', 'ap-topic-stats-data', 12, false, 'A', 'Exploring Data & Probability', 'medium', 'Which sampling method divides a population into homogeneous subgroups (such as grade levels) and takes a simple random sample from within every subgroup?', '["Stratified random sampling","Cluster sampling","Convenience sampling","Systematic sampling"]'::jsonb, 'Stratified random sampling partitions the population into non-overlapping homogeneous strata and then draws an independent SRS from each stratum, guaranteeing representation across all groups.'),
  ('ap-topic-stats-data_q13', 'ap-topic-stats-data', 13, false, 'A', 'Exploring Data & Probability', 'hard', 'A test of $H_0: \mu = 50$ versus $H_a: \mu > 50$ yields a $p$-value of 0.032. At the $\alpha = 0.05$ significance level, what is the appropriate conclusion?', '["Reject $H_0$; there is convincing statistical evidence that the true mean is greater than 50","Fail to reject $H_0$; there is convincing statistical evidence that the true mean is equal to 50","Accept $H_0$; there is insufficient evidence that the true mean is greater than 50","Reject $H_a$; the test is inconclusive"]'::jsonb, 'Since $p = 0.032 < \alpha = 0.05$, we reject $H_0$. There is statistically significant evidence at the 5% level to support the alternative hypothesis that $\mu > 50$.'),
  ('ap-topic-stats-data_q14', 'ap-topic-stats-data', 14, false, 'A', 'Exploring Data & Probability', 'medium', 'A medical test has sensitivity $P(+|\text{Disease}) = 0.95$ and specificity $P(-|\text{No Disease}) = 0.90$. If disease prevalence is $1\%$, what is the probability that a randomly chosen person tests positive?', '["0.1085","0.0095","0.0990","0.9500"]'::jsonb, 'By the Law of Total Probability: $P(+) = P(+|D)P(D) + P(+|D^c)P(D^c)$. Here $P(D) = 0.01$, $P(D^c) = 0.99$. $P(+|D^c) = 1 - 0.90 = 0.10$. Thus $P(+) = (0.95)(0.01) + (0.10)(0.99) = 0.0095 + 0.0990 = 0.1085$.'),
  ('ap-topic-stats-data_q15', 'ap-topic-stats-data', 15, false, 'A', 'Exploring Data & Probability', 'medium', 'What does the Central Limit Theorem state regarding the sampling distribution of the sample mean $\bar{x}$ when sample size $n$ is sufficiently large ($n \ge 30$)?', '["The distribution of $\\bar{x}$ is approximately normal regardless of the shape of the population distribution","The population distribution itself transforms into a normal distribution","The standard deviation of $\\bar{x}$ increases proportionally with $\\sqrt{n}$","The sample mean $\\bar{x}$ will equal the population mean $\\mu$ in every single sample"]'::jsonb, 'The Central Limit Theorem guarantees that the sampling distribution of sample means becomes approximately normal as $n$ grows large, even if the underlying population distribution is skewed or bimodal.'),
  ('ap-topic-stats-data_q16', 'ap-topic-stats-data', 16, false, 'A', 'Exploring Data & Probability', 'medium', 'The least-squares regression line for predicting plant height ($y$, in cm) from days of growth ($x$) is $\hat{y} = 4.5 + 1.8x$. For a plant measured at day 10 with an actual height of 25 cm, what is the residual?', '["2.5 cm","-2.5 cm","22.5 cm","0 cm"]'::jsonb, 'Predicted height: $\hat{y} = 4.5 + 1.8(10) = 4.5 + 18 = 22.5\text{ cm}$. Residual $= y - \hat{y} = 25 - 22.5 = +2.5\text{ cm}$.'),
  ('ap-topic-stats-data_q17', 'ap-topic-stats-data', 17, false, 'A', 'Exploring Data & Probability', 'hard', 'Random variables $X$ and $Y$ are independent with $\mu_X = 10$, $\sigma_X = 3$, $\mu_Y = 6$, and $\sigma_Y = 4$. What is the standard deviation of $W = X - Y$?', '["5","1","7","25"]'::jsonb, 'For independent random variables, variances always add: $\text{Var}(X - Y) = \text{Var}(X) + \text{Var}(Y) = 3^2 + 4^2 = 9 + 16 = 25$. The standard deviation is $\sigma_W = \sqrt{25} = 5$.'),
  ('ap-topic-stats-data_q18', 'ap-topic-stats-data', 18, false, 'A', 'Exploring Data & Probability', 'medium', 'What is a key difference between an observational study and an experiment?', '["In an experiment, researchers actively impose treatments on experimental units to establish causation; in an observational study, no treatments are assigned","Observational studies allow establishing cause-and-effect relationships, whereas experiments do not","Experiments cannot utilize random assignment","Observational studies always eliminate confounding variables"]'::jsonb, 'An experiment deliberately applies treatments to units to observe consequences, enabling causal inference. An observational study only observes and measures conditions without intervening.'),
  ('ap-topic-stats-data_q19', 'ap-topic-stats-data', 19, false, 'A', 'Exploring Data & Probability', 'hard', 'A two-way table shows 40 men and 60 women. 16 men and 24 women prefer Option A. Are gender and preference for Option A independent?', '["Yes, because $P(\\text{Option A}|\\text{Men}) = P(\\text{Option A}|\\text{Women}) = 0.40$","No, because more women than men chose Option A","No, because the total counts are unequal","Yes, because $16 + 24 = 40$"]'::jsonb, '$P(\text{A}|\text{Men}) = \frac{16}{40} = 0.40$. $P(\text{A}|\text{Women}) = \frac{24}{60} = 0.40$. Overall $P(\text{A}) = \frac{40}{100} = 0.40$. Since the conditional probabilities equal the overall probability, the events are independent.'),
  ('ap-topic-stats-data_q20', 'ap-topic-stats-data', 20, false, 'A', 'Exploring Data & Probability', 'medium', 'Which statistic is resistant to extreme outliers?', '["Interquartile Range (IQR)","Range","Mean","Standard deviation"]'::jsonb, 'The Interquartile Range (IQR) and median are resistant statistics because they depend on the middle 50% of ranked observations, remaining unaffected by extreme values in the tails.'),
  ('ap-topic-phys1-kinematics_q1', 'ap-topic-phys1-kinematics', 1, false, 'D', 'Kinematics', 'easy', 'A ball is thrown upward with an initial velocity of 20 m/s. How long will the ball take to reach its maximum height?</p>', '["19.6 s","9.8 s","6.3 s","2.04 s"]'::jsonb, 'Given the initial velocity of 20 m/s, we know that the ball is decelerated by gravity at a rate of 9.8 m/$s^{2}$. Therefore, we need to know how long gravity will take to decelerate the ball to zero velocity. Clearly, from the definition of acceleration, dividing 20 m/s by 9.8 m/$s^{2}$ gives the answer: 2.04 s.</p></li>
<li>'),
  ('ap-topic-phys1-kinematics_q2', 'ap-topic-phys1-kinematics', 2, false, 'B', 'Kinematics', 'easy', 'An airplane lands on a runway with a velocity of 150 m/s. How far will it travel until it stops if its rate of deceleration is constant at −3 m/$s^{2}$?</p>', '["525 m","3,750 m","6,235 m","9,813 m"]'::jsonb, 'We do not know the time needed to stop, but we do know that the final velocity is zero. If we use the formula</p> v_y = v_0\sin\theta - gt = 40\sin(30^\circ) - (9.8)(1) = 20 - 9.8 = 10.2\text{ m/s} $$
<p class="expt">and substitute 150 m/s for the initial velocity and −3 m/$s^{2}$ for the deceleration, we get the answer: 3,750 m.</p></li>
<li>'),
  ('ap-topic-phys1-kinematics_q3', 'ap-topic-phys1-kinematics', 3, false, 'C', 'Kinematics', 'easy', 'A ball is thrown downward from the top of a roof with a speed of 25 m/s. After 2 s, its velocity will be</p>', '["19.6 m/s","−5.4 m/s","−44.6 m/s","44.6 m/s"]'::jsonb, 'The initial velocity is −25 m/s downward, so $v$ = −(25) − (9.8)(2) = −44.6 m/s.</p></li>
<li>'),
  ('ap-topic-phys1-kinematics_q4', 'ap-topic-phys1-kinematics', 4, false, 'C', 'Kinematics', 'medium', 'A rocket is propelled upward with an acceleration of 25 m/$s^{2}$ for 5 s. After that time, the engine is shut off, and the rocket continues to move upward. The maximum height, in meters, that the rocket will reach is</p>', '["900","1,000","1,100","1,200"]'::jsonb, 'The rocket accelerates from rest, so the first distance traveled in 5 s is given by</p> v_x = v_0\cos(30^\circ) = 40(0.866) = 34.6\text{ m/s} $$
<p class="expt">Substituting the values for time (5 s) and acceleration (25 m/$s^{2}$) gives $y_{1}$ = 312.5 m. After 5 s of accelerating, the rocket has a velocity of 125 m/s. After this time, the engine stops and the rocket is decelerated by gravity as it continues to move upward. The time to decelerate to zero is found by dividing 125 m/s by the acceleration of gravity. Thus, 125/9.8 = 12.76 s.</p>
<p class="expt">The distance traveled during that time is added to the first accelerated distance. The second distance is given by</p> v = \sqrt{v_x^2 + v_y^2} = \sqrt{(34.6)^2 + (10.2)^2} = 36.1\text{ m/s} $$
<p class="expt">The total distance traveled is therefore equal to 1,108 m or, rounded off, 1,100 m.</p></li>
<li>'),
  ('ap-topic-phys1-kinematics_q5', 'ap-topic-phys1-kinematics', 5, false, 'C', 'Kinematics', 'medium', 'The total distance traveled by the object during the indicated 14 s is</p>', '["7.5 m","25 m","62.5 m","77.5 m"]'::jsonb, 'The total distance traveled by the object in 14 s is equal to the total area under the graph. Breaking the figure up into triangles and rectangles, we find that their areas add up to 62.5 m (recall that distance is a scalar).</p></li>
<li>'),
  ('ap-topic-phys1-kinematics_q6', 'ap-topic-phys1-kinematics', 6, false, 'A', 'Kinematics', 'medium', 'The total displacement of the object during the 14 s indicated is</p>', '["7.5 m","25 m","62.5 m","77.5 m"]'::jsonb, 'The total displacement for the object is the sum of the positive (forward) and negative (backward) areas, representing the fact that the object moves away from the origin and then back (as indicated by the velocity vs. time graph), going below the $x$-axis. Adding and subtracting the proper areas: 35 − 2.5 − 20 − 5 = 7.5 m for the final displacement.</p></li>
<li>'),
  ('ap-topic-phys1-kinematics_q7', 'ap-topic-phys1-kinematics', 7, false, 'B', 'Kinematics', 'medium', 'The average velocity over the whole time, in meters per second, of the object is</p>', '["0","0.5","2.5","4.5"]'::jsonb, 'Average velocity is the change in displacement for the object over the change in time (not distance). Since from question 6 we know the displacement change to be 7.5 m in 14 s, the average velocity is therefore 0.53 m/s.</p></li>
<li>'),
  ('ap-topic-phys1-kinematics_q8', 'ap-topic-phys1-kinematics', 8, false, 'A', 'Kinematics', 'medium', 'What is the total change in velocity for the object whose acceleration versus time graph is given below?</p>
<p class="center1"><img alt="" class="w53" role="presentation" src="images/f062-01.jpg"/></p>', '["40 m/s","−40 m/s","80 m/s","−80 m/s"]'::jsonb, 'The change in velocity for the object is equal to the area under the graph, which is equal to 1/2 (+8)(10) = +40 m/s.</p></li>
<li>'),
  ('ap-topic-phys1-kinematics_q9', 'ap-topic-phys1-kinematics', 9, false, 'B', 'Kinematics', 'hard', 'An object has an initial velocity of 15 m/s. How long must it accelerate at a constant rate of 3 m/$s^{2}$ before its average velocity is equal to twice its initial velocity?</p>', '["5 s","10 s","15 s","20 s"]'::jsonb, 'For uniformly accelerated motion, the average velocity is</p> a_c = \frac{v^2}{r} = \frac{4^2}{2} = 8\text{ m/s}^2 $$
<p class="expt">The question requires that the average velocity be equal to twice the initial velocity; thus, if the average velocity is 30 m/s, the final velocity attained must be 45 m/s. Now the question is, how long must the object accelerate from 15 m/s to achieve a speed of 45 m/s? A change in velocity of 30 m/s at a rate of 3 m/$s^{2}$ for 10 s is implied.</p></li>
<li>'),
  ('ap-topic-phys1-kinematics_q10', 'ap-topic-phys1-kinematics', 10, false, 'B', 'Kinematics', 'hard', 'A projectile is launched at an angle of 45° with a velocity of 250 m/s. If air resistance is neglected, the magnitude of the horizontal velocity of the projectile at the time it reaches maximum altitude is equal to</p>', '["0 m/s","175 m/s","200 m/s","250 m/s"]'::jsonb, 'The horizontal component of velocity remains constant in the absence of resistive forces and is equal to $v$<sub>$i$</sub> cos θ. Substituting the known numbers, we get $v$<sub>$x$</sub> = (250)(0.7) = 175 m/s.</p></li>
<li>'),
  ('ap-topic-phys1-kinematics_q11', 'ap-topic-phys1-kinematics', 11, false, 'D', 'Kinematics', 'hard', 'A projectile is launched horizontally with a velocity of 25 m/s from the top of a 75-m height. How many seconds will the projectile take to reach the bottom?</p>', '["15.5","9.75","6.31","3.91"]'::jsonb, 'The time to fall is given by the free-fall formula:</p>
<p class="center1">$t = \sqrt{\frac{2y}{g}}$</p>
<p class="expt">If we substitute the known numbers, we get 3.91 s for the time.</p></li>
<li>'),
  ('ap-topic-phys1-kinematics_q12', 'ap-topic-phys1-kinematics', 12, false, 'A', 'Kinematics', 'hard', 'At a launch angle of 45°, the range of a launched projectile is given by</p>', '["$ 0 $","$ 2\\text{ m/s}^2 $","$ 4\\text{ m/s}^2 $","$ 8\\text{ m/s}^2 $"]'::jsonb, 'From the formula for range, we see that, at 45°, sin 2θ = 1, and so</p>
<p class="center1">$R = \frac{v_i^2}{g}$</p></li>
<li>'),
  ('ap-topic-phys1-kinematics_q13', 'ap-topic-phys1-kinematics', 13, false, 'A', 'Kinematics', 'hard', 'A projectile is launched at a certain angle. After 4 s, it hits the top of a building 500 m away. The height of the building is 50 m. The projectile was launched at an angle of</p>', '["14°","21°","37°","76°"]'::jsonb, 'We know that, after 4 s, the projectile has traveled horizontally 500 m. Therefore, the horizontal velocity was a constant 125 m/s and is equal to $v$<sub>$i$</sub> cos θ. We also know that, after 4 s, the $y$-position of the projectile is 50 m. Thus, we can write:</p>
<p class="center1">\$50 = 4 v_i \sin\theta - 4.9(4)^2 = 4 v_i \sin\theta - 78.4$</p>
<p class="expt">Therefore, $v$<sub>$i$</sub> cos θ = 125, $v$<sub>$i$</sub> sin θ = 32.1, and tan θ = 0.2568, so θ = 14.4°.</p></li>
<li>'),
  ('ap-topic-phys1-kinematics_q14', 'ap-topic-phys1-kinematics', 14, false, 'C', 'Kinematics', 'hard', 'The operator of a boat wishes to cross a 5-km-wide river that is flowing to the east at 10 m/s. He wants to reach the exact point on the opposite shore 15 min after starting. With what speed and in what direction should the boat travel?</p>', '["11.2 m/s at 26.6° E of N","8.66 m/s at 63.4° W of N","11.4 m/s at 60.9° W of N","8.66 m/s at 26.6° E of N"]'::jsonb, 'The river is flowing at 10 m/s to the right (east), and the resultant desired velocity is 5.55 m/s up (north). Therefore, the actual velocity, relative to the river, is heading W of N. By the Pythagorean theorem, the velocity of the boat must be 11.4 m/s. The angle is given by the tangent function. In the diagram below, not drawn to scale but correct for orientation, tan (θ) = $ a_c = \frac{v^2}{r} $ = 1.8. Therefore, θ = 60.9° W of N.</p>
<p class="center1"><img alt="" class="w60" role="presentation" src="images/f065-02.jpg"/></p></li>
</ol>
</section>
</section>
<section>'),
  ('ap-topic-phys1-kinematics_q15', 'ap-topic-phys1-kinematics', 15, false, 'A', 'ap-topic-phys1-kinematics', 'medium', 'A cart moves along a straight horizontal track. Its position is given by $x(t) = 2.0t^3 - 9.0t^2 + 12t$ (in meters and seconds). At what time(s) is the cart momentarily at rest?', '["$t = 1.0\\text{ s}$ and $t = 2.0\\text{ s}$","$t = 1.5\\text{ s}$ only","$t = 0\\text{ s}$ and $t = 3.0\\text{ s}$","$t = 2.0\\text{ s}$ and $t = 4.0\\text{ s}$"]'::jsonb, '$v(t) = dx/dt = 6t^2 - 18t + 12 = 6(t^2 - 3t + 2) = 6(t - 1)(t - 2)$. Velocity is zero when $t = 1.0\text{ s}$ and $t = 2.0\text{ s}$.'),
  ('ap-topic-phys1-kinematics_q16', 'ap-topic-phys1-kinematics', 16, false, 'B', 'ap-topic-phys1-kinematics', 'easy', 'A stone is thrown vertically upward from ground level with speed $v_0$. If air resistance is negligible, which graph best describes its acceleration as a function of time during flight?', '["A line sloping downward from $+g$ to $-g$","A horizontal line at $-g$ (constant negative acceleration)","A line that is positive on the way up and negative on the way down","A parabola opening downward"]'::jsonb, 'Near the surface of the Earth, gravitational acceleration is constant and downward: $a = -g = -9.8\text{ m/s}^2$ at all points during free fall.'),
  ('ap-topic-phys1-kinematics_q17', 'ap-topic-phys1-kinematics', 17, false, 'C', 'ap-topic-phys1-kinematics', 'medium', 'Car A starts from rest with constant acceleration $a$. At the same instant, Car B passes Car A traveling at constant speed $v$. How much time elapses before Car A overtakes Car B?', '["$t = \\dfrac{v}{a}$","$t = \\dfrac{v}{2a}$","$t = \\dfrac{2v}{a}$","$t = \\sqrt{\\dfrac{2v}{a}}$"]'::jsonb, '$x_A(t) = \frac{1}{2}at^2$ and $x_B(t) = vt$. Setting $x_A = x_B \implies \frac{1}{2}at^2 = vt \implies t(at - 2v) = 0 \implies t = \frac{2v}{a}$.'),
  ('ap-topic-phys1-kinematics_q18', 'ap-topic-phys1-kinematics', 18, false, 'D', 'ap-topic-phys1-kinematics', 'easy', 'A projectile is launched with speed $v_0$ at angle $\theta$ above the horizontal. At the apex of its parabolic trajectory, what are its speed and acceleration?', '["Speed is zero, acceleration is zero","Speed is $v_0\\cos\\theta$, acceleration is zero","Speed is zero, acceleration is $g$ directed downward","Speed is $v_0\\cos\\theta$, acceleration is $g$ directed downward"]'::jsonb, 'At the peak, vertical velocity $v_y = 0$, while horizontal velocity remains $v_x = v_0\cos\theta$. Acceleration throughout flight is due to gravity alone: $g$ downward.'),
  ('ap-topic-phys1-kinematics_q19', 'ap-topic-phys1-kinematics', 19, false, 'A', 'ap-topic-phys1-kinematics', 'medium', 'A velocity-time graph of an object moving along the $x$-axis shows a triangle of base $4.0\text{ s}$ and height $+6.0\text{ m/s}$, followed by a triangle below the axis of base $2.0\text{ s}$ and depth $-3.0\text{ m/s}$. What is the net displacement over the $6.0\text{ s}$ interval?', '["$+9.0\\text{ m}$","$+12.0\\text{ m}$","$+6.0\\text{ m}$","$+15.0\\text{ m}$"]'::jsonb, 'Displacement is the area under $v-t$: $A_1 = \frac{1}{2}(4)(6) = +12\text{ m}$; $A_2 = \frac{1}{2}(2)(-3) = -3\text{ m}$. Net displacement $= 12 - 3 = +9.0\text{ m}$.'),
  ('ap-topic-phys1-kinematics_q20', 'ap-topic-phys1-kinematics', 20, false, 'B', 'ap-topic-phys1-kinematics', 'easy', 'A ball dropped from height $H$ hits the ground with speed $v$. From what height must it be dropped to hit the ground with speed $2v$ (neglecting air drag)?', '["$2H$","$4H$","$\\sqrt{2}H$","$8H$"]'::jsonb, '$v^2 = 2gH \implies H \propto v^2$. To double the impact speed ($2v$), the required height must be $(2)^2 H = 4H$.'),
  ('ap-topic-phys1-dynamics_q1', 'ap-topic-phys1-dynamics', 1, false, 'A', 'Newton''s Laws & Forces', 'easy', 'In the situation shown below, what is the tension in string 1?</p>
<p class="center1"><img alt="" class="w51" role="presentation" src="images/f082-01.jpg"/></p>', '["69.3 N","98 N","138.6 N","147.6 N"]'::jsonb, 'We need to apply the second law for static equilibrium. This means that we must resolve the tensions into their $x$- and $y$-components. For $T_{1}$, we have $T_{1}$ cos 45 and $T_{1}$ sin 45. In equilibrium, the sum of all the $x$ forces must equal zero. This means that $T_{1}$ cos 45 = $T_{2}$ (since $T_{2}$ is entirely horizontal). The $y$-component of $T_{1}$ must balance the weight = <i>mg</i> = 49 N. Thus, $T_{1}$ sin 45 = 49 N and $T_{1}$ = 69.3 N.</p>
<p class="center1"><img alt="" class="w28" role="presentation" src="images/f085-01.jpg"/></p></li>
<li>'),
  ('ap-topic-phys1-dynamics_q2', 'ap-topic-phys1-dynamics', 2, false, 'B', 'Newton''s Laws & Forces', 'easy', 'Two masses, $M$ and $m$, are hung over a massless, frictionless pulley as shown below. If $M$ &gt; $m$, what is the downward acceleration of mass $M$?</p>
<p class="center1"><img alt="" class="w51" role="presentation" src="images/f082-02.jpg"/></p>', '["$g$","$ \\mu_s = 0.5 $","$ \\mu_s > 0.5 $","$ \\mu_s < 0.5 $"]'::jsonb, 'The free-body diagrams for both masses, $M$ and $m$, look like this:</p>
<p class="center1"><img alt="" class="w43" role="presentation" src="images/f085-02.jpg"/></p>
<p class="exp">The large mass is accelerating downward, while the small mass is accelerating upward. The tension in the string is directed upward, while gravity, given by the weight, is directed downward. Using the second law for accelerated motion, we must show that for each mass, ∑$F$<sub>$y$</sub> = <i>ma</i>. Thus, we have</p>
<p class="center1">$T - Mg = -Ma \text{ and } T - mg = ma$</p>
<p class="exp">Eliminating the tension $T$ and solving for $a$ gives us ($M$ − $m$)$g$/($M +m$).</p></li>
<li>'),
  ('ap-topic-phys1-dynamics_q3', 'ap-topic-phys1-dynamics', 3, false, 'D', 'Newton''s Laws & Forces', 'easy', 'A 0.25-kg mass is attached to a string and swung in a vertical circle whose radius is 0.75 m. At the bottom of the circle, the mass is observed to have a speed of 10 m/s. What is the magnitude of the tension in the string at that point?</p>', '["2.45 N","5.78 N","22.6 N","35.7 N"]'::jsonb, 'A sketch of the situation is shown below:</p>
<p class="center1">$\text{[Diagram of vertical circle: radius } r = 0.5\text{ m}, \text{mass } m, \text{tension } \vec{T}, \text{gravity } m\vec{g}]$</p>
<p class="exp">At the lowest point, the downward force of gravity is opposed by the upward tension in the string. Note that doing a quick tip-to-tail graphical solution of the force vectors must result in an upward (inward) net force. Thus, we can write</p>
<p class="center1">$T - mg = \frac{mv^2}{r}$</p>
<p class="exp">Substituting in the given values and solving for $T$ gives us 35.7 N.</p></li>
<li>'),
  ('ap-topic-phys1-dynamics_q4', 'ap-topic-phys1-dynamics', 4, false, 'A', 'Newton''s Laws & Forces', 'medium', 'A car and driver have a combined mass of 1,000 kg. The car passes over the top of a hill that has a radius of curvature equal to 10 m. The speed of the car at that instant is 5 m/s. What is the force of the hill on the car as it passes over the top?</p>', '["7,300 N up","7,300 N down","12,300 N up","12,300 N down"]'::jsonb, 'As the car goes over the hill, the force that the hill exerts on the car is the normal force, \vec{N}. This is opposed, however, by the downward force of gravity. The combination produces (as in question 3) the centripetal force \vec{F}<i><sub>c</sub></i>. Using our circular motion convention of inward forces being positive, we can write</p>
<p class="center1">$mg - N = \frac{mv^2}{r}$</p>
<p class="exp">A sketch is shown below. Note that doing a quick tip-to-tail graphical solution of the force vectors must result in a downward (inward) net force. Substituting in the given values and solving for $N$ gives 7,300 N upward.</p>
<p class="center1"><img alt="" class="w53" role="presentation" src="images/f085-07.jpg"/></p></li>
<li>'),
  ('ap-topic-phys1-dynamics_q5', 'ap-topic-phys1-dynamics', 5, false, 'D', 'Newton''s Laws & Forces', 'medium', 'A hockey puck with a mass of 0.3 kg is sliding along ice that can be considered frictionless. The puck’s velocity is 20 m/s. The puck now crosses over onto a floor that has a coefficient of kinetic friction equal to 0.35. How far will the puck travel across the floor before it stops?</p>', '["3 m","87 m","48 m","58 m"]'::jsonb, 'With horizontal motion, the normal force is equal to the force of gravity. When the puck is moving with constant velocity, no net force is acting on it. Thus, when friction acts to slow the puck down, the friction is the only net force. Therefore, we write</p>
<p class="center1">$f = \mu N = \mu mg = -ma$</p>
<p class="exp">(since the puck is decelerating). Substituting the known numbers gives a deceleration of −3.43 m/$s^{2}$. Now, the final velocity will be zero; and since the time to stop is unknown, we use the following kinematic expression to solve for the stopping distance:</p>
<p class="center1">$-v_i^2 = 2ax$</p>
<p class="exp">Substituting the known numbers, we obtain approximately 58 m as the distance the puck will travel before stopping.</p></li>
<li>'),
  ('ap-topic-phys1-dynamics_q6', 'ap-topic-phys1-dynamics', 6, false, 'C', 'Newton''s Laws & Forces', 'medium', 'A spring with a stiffness constant $k$ = 50 N/m has a natural length of 0.45 m. It is attached to the top of an incline that makes a 30° angle with the horizontal. The incline is 2.4 m long. A mass of 2 kg is attached to the spring, causing it to be stretched down the incline. How far down the incline does the end of the spring rest?</p>', '["0.196 m","0.45 m","0.646 m","0.835 m"]'::jsonb, 'A sketch of the situation is given below. The spring constant is $k$ = 50 N/m.</p>
<p class="center1"><img alt="" class="w60" role="presentation" src="images/f086-03.jpg"/></p>
<p class="exp">According to Hooke’s law, $F$<sub>$s$</sub> = <i>kx</i>, where $x$ is the elongation in excess of the spring’s natural length (here 0.45 m). The force, in this case, is provided by the component of weight parallel to the incline, which is given by <i>mg</i> sin θ. Substituting the known numbers gives us an elongation of $x$ = 0.196 m. Since this must be in excess of the spring’s natural length, the answer is 0.646 m.</p></li>
<li>'),
  ('ap-topic-phys1-dynamics_q7', 'ap-topic-phys1-dynamics', 7, false, 'C', 'Newton''s Laws & Forces', 'medium', 'A 20-N force is pushing two blocks horizontally along a frictionless floor as shown below.</p>
<p class="center1"><img alt="" class="w62" role="presentation" src="images/f083-01.jpg"/></p>
<p class="exp">What is the force that the 8-kg mass exerts on the 2-kg mass?</p>', '["4 N","8 N","16 N","20 N"]'::jsonb, 'The 20-N force is pushing on a total mass of 10 kg. Thus, using \vec{F} = $m$\vec{a}, we have the acceleration of both blocks equal to 2 m/$s^{2}$. We draw a free-body diagram for the 2-kg mass as shown below.</p>
<p class="center1"><img alt="" class="w71" role="presentation" src="images/f086-04.jpg"/></p>
<p class="exp">Let $P$ represent the force that the 8-kg mass exerts on the 2-kg mass. Writing the second law of motion, we get \vec{F} − $P = m$\vec{a}. To find $P$, we substitute the known numbers: 20 − $P$ = (2)(2) = 4. Thus, $P$ = 16 N.</p></li>
<li>'),
  ('ap-topic-phys1-dynamics_q8', 'ap-topic-phys1-dynamics', 8, false, 'C', 'Newton''s Laws & Forces', 'medium', 'A force of 20 N acts horizontally on a mass of 10 kg being pushed along a frictionless incline that makes a 30° angle with the horizontal, as shown below.</p>
<p class="center1"><img alt="" class="w48" role="presentation" src="images/f083-02.jpg"/></p>
<p class="exp">The magnitude of the acceleration of the mass up the incline is equal to</p>', '["1.9 m/$s^{2}$","2.2 m/$s^{2}$","3.17 m/$s^{2}$","3.87 m/$s^{2}$"]'::jsonb, 'From the given diagram, we see that the force necessary to move the mass up the incline must be in excess of the component force of gravity trying to pull the mass down the incline. The component of gravity down the incline is always given by <i>mg</i> sin θ. Resolving the given force into a component parallel to the incline and a component perpendicular to the incline, we find that the force up the incline is, at the same angle, $F$ cos θ. Thus, in general we would write:</p>
<p class="center1">$F\cos\theta - mg\sin\theta = ma$</p>
<p class="exp">Substituting the known numbers gives $a$ = 3.17 m/s<span><sup>2</sup></span>.</p></li>
<li>'),
  ('ap-topic-phys1-dynamics_q9', 'ap-topic-phys1-dynamics', 9, false, 'C', 'Newton''s Laws & Forces', 'hard', 'According to the diagram below, what is the tension in the connecting string if the table is frictionless?</p>
<p class="center1"><img alt="" class="w66" role="presentation" src="images/f083-03.jpg"/></p>', '["6.4 N","13 N","19.7 N","25 N"]'::jsonb, 'From the given diagram, we see that the 4-kg mass is accelerating to the right and the 2-kg mass is accelerating up. Thus, we write that the sum of all forces, in each direction, equals <i>ma</i>. In the $x$-direction, we have (since the tension in the string will try to pull left) −$T$ + 20 = 4$a$. In the $y$-direction, the tension pulls up against gravity. We therefore write $T$ − 19.6 = 2$a$. Solving for $T$ by eliminating $a$, we get $T$ = 19.7 N.</p></li>
<li>'),
  ('ap-topic-phys1-dynamics_q10', 'ap-topic-phys1-dynamics', 10, false, 'A', 'Newton''s Laws & Forces', 'hard', 'A mass, $M$, is released from rest on an incline that makes a 42° angle with the horizontal. In 3 s, the mass is observed to have gone a distance of 3 m. What is the coefficient of kinetic friction between the mass and the surface of the incline?</p>', '["0.8","0.7","0.6","0.5"]'::jsonb, 'We know that the mass accelerates from rest uniformly in 3 s and goes a distance of 3 m. Thus, we can say that</p>
<p class="center1">$d = \frac{1}{2}at^2$</p>
<p class="exp">Substituting the known number gives us an acceleration of 0.67 m/$s^{2}$. On an incline, the normal force is given by <i>mg</i> cos θ, and so friction can be expressed as $f$ = <i>μmg</i> cos θ. Once again, this force opposes the downward force of gravity parallel to the incline, given by −<i>mg</i> sin θ. In the downward direction, these two forces are added together and set equal to −<i>ma</i>. Thus, we write for this case</p>
<p class="center1">$\mu (M)(9.8)\cos 42^\circ - (M)(9.8)\sin 42^\circ = -(M)(0.67)$</p>
<p class="exp">The masses all cancel out, and solving for $\mu$ gives 0.8 as the coefficient of kinetic friction.</p></li>
</ol>
</section>
</section>
<section>'),
  ('ap-topic-phys1-dynamics_q11', 'ap-topic-phys1-dynamics', 11, false, 'A', 'ap-topic-phys1-dynamics', 'medium', 'A $5.0\text{ kg}$ block rests on a horizontal frictionless surface. A force of $20\text{ N}$ acts at an angle of $30^\circ$ below the horizontal. What is the normal force exerted by the surface on the block ($g = 9.8\text{ m/s}^2$)?', '["$59\\text{ N}$","$49\\text{ N}$","$39\\text{ N}$","$69\\text{ N}$"]'::jsonb, 'Vertical equilibrium: $F_N - mg - F\sin 30^\circ = 0 \implies F_N = 5.0(9.8) + 20(0.5) = 49 + 10 = 59\text{ N}$.'),
  ('ap-topic-phys1-dynamics_q12', 'ap-topic-phys1-dynamics', 12, false, 'B', 'ap-topic-phys1-dynamics', 'medium', 'Two masses $m_1 = 3\text{ kg}$ and $m_2 = 5\text{ kg}$ are connected by a light string over an ideal frictionless pulley (Atwood machine). What is the magnitude of the acceleration of the system?', '["$\\frac{1}{2}g$","$\\frac{1}{4}g$","$\\frac{3}{8}g$","$\\frac{5}{8}g$"]'::jsonb, '$a = \frac{(m_2 - m_1)g}{m_1 + m_2} = \frac{(5 - 3)g}{3 + 5} = \frac{2g}{8} = \frac{1}{4}g$.'),
  ('ap-topic-phys1-dynamics_q13', 'ap-topic-phys1-dynamics', 13, false, 'C', 'ap-topic-phys1-dynamics', 'easy', 'An elevator of mass $M$ accelerates upward at $a = 0.20g$. What is the tension in the supporting cable?', '["$0.80Mg$","$1.00Mg$","$1.20Mg$","$1.44Mg$"]'::jsonb, 'Newton''s second law: $T - Mg = Ma \implies T = M(g + a) = M(g + 0.20g) = 1.20Mg$.'),
  ('ap-topic-phys1-dynamics_q14', 'ap-topic-phys1-dynamics', 14, false, 'D', 'ap-topic-phys1-dynamics', 'easy', 'A block slides down an incline of angle $\theta$ at constant speed. What is the coefficient of kinetic friction $\mu_k$ between the block and the incline?', '["$\\sin\\theta$","$\\cos\\theta$","$\\cot\\theta$","$\\tan\\theta$"]'::jsonb, 'At constant velocity, net force along the ramp is zero: $mg\sin\theta - f_k = 0 \implies mg\sin\theta = \mu_k mg\cos\theta \implies \mu_k = \tan\theta$.'),
  ('ap-topic-phys1-dynamics_q15', 'ap-topic-phys1-dynamics', 15, false, 'A', 'ap-topic-phys1-dynamics', 'medium', 'A person of mass $m$ stands on a scale in an elevator that is moving downward while slowing down. How does the scale reading compare to the person''s true weight $mg$?', '["The scale reading is greater than $mg$","The scale reading is less than $mg$","The scale reading is equal to $mg$","The scale reading is zero"]'::jsonb, 'Moving downward and slowing down means the acceleration is directed upward: $F_N - mg = ma_{up} \implies F_N = m(g + a_{up}) > mg$.'),
  ('ap-topic-phys1-dynamics_q16', 'ap-topic-phys1-dynamics', 16, false, 'B', 'ap-topic-phys1-dynamics', 'medium', 'A $2.0\text{ kg}$ object is pushed against a vertical wall with a horizontal force $F$. If the coefficient of static friction is $\mu_s = 0.40$, what minimum force $F$ prevents the object from slipping downward ($g = 10\text{ m/s}^2$)?', '["$20\\text{ N}$","$50\\text{ N}$","$8.0\\text{ N}$","$80\\text{ N}$"]'::jsonb, 'Vertical balance: $f_s = mg = 2.0(10) = 20\text{ N}$. Since $f_s \le \mu_s F_N$ and $F_N = F$, we have $20 \le 0.40F \implies F \ge 50\text{ N}$.'),
  ('ap-topic-phys1-dynamics_q17', 'ap-topic-phys1-dynamics', 17, false, 'C', 'ap-topic-phys1-dynamics', 'easy', 'According to Newton''s third law, the reaction force to the gravitational force exerted by the Earth on an apple is:', '["The upward normal force from the tree branch","Air resistance acting on the falling apple","The gravitational force exerted by the apple on the Earth","The inertia of the apple resisting motion"]'::jsonb, 'Newton''s third law pairs involve the same interaction between two objects. Earth pulls apple down $\iff$ apple pulls Earth up with equal magnitude.'),
  ('ap-topic-phys1-dynamics_q18', 'ap-topic-phys1-dynamics', 18, false, 'D', 'ap-topic-phys1-dynamics', 'medium', 'A car of mass $m$ negotiates an unbanked circular curve of radius $R$ at constant speed $v$. What force provides the necessary centripetal acceleration?', '["Kinetic friction between the tires and road","The normal force directed inward","The engine''s forward drive force","Static friction between the car''s tires and the road surface"]'::jsonb, 'For a car turning without skidding on a flat road, static friction directed perpendicular to velocity toward the center of curvature provides $F_c = mv^2/R$.'),
  ('ap-topic-phys1-dynamics_q19', 'ap-topic-phys1-dynamics', 19, false, 'A', 'ap-topic-phys1-dynamics', 'medium', 'Two blocks $m_A = 2\text{ kg}$ and $m_B = 4\text{ kg}$ are in contact on a frictionless floor. A horizontal force $F = 18\text{ N}$ is applied to $m_A$, pushing both blocks. What is the contact force between $m_A$ and $m_B$?', '["$12\\text{ N}$","$6\\text{ N}$","$18\\text{ N}$","$9\\text{ N}$"]'::jsonb, 'Total acceleration $a = \frac{F}{m_A + m_B} = \frac{18}{6} = 3\text{ m/s}^2$. The only horizontal force on $m_B$ is the contact force: $F_{AB} = m_B a = 4 \times 3 = 12\text{ N}$.'),
  ('ap-topic-phys1-dynamics_q20', 'ap-topic-phys1-dynamics', 20, false, 'B', 'ap-topic-phys1-dynamics', 'medium', 'An object is subjected to a drag force modeled as $F_d = -bv$. Which of the following expressions gives the terminal velocity of the object falling under gravity?', '["$v_t = \\dfrac{b}{mg}$","$v_t = \\dfrac{mg}{b}$","$v_t = \\sqrt{\\dfrac{mg}{b}}$","$v_t = \\dfrac{mg}{b^2}$"]'::jsonb, 'Terminal velocity occurs when net acceleration is zero: $mg - bv_t = 0 \implies v_t = \frac{mg}{b}$.')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-physc-kinematics_q1', 'ap-topic-physc-kinematics', 1, false, 'A', 'Uniform Circular Motion & Kinematics', 'easy', 'An object that''s moving with constant speed travels once around a circular path. Which of the following is/are true concerning this motion?  I. The displacement is zero.  II. The average speed is zero.  III. The acceleration is zero.', '["I only","I and II only","I and III only","III only","II and III only"]'::jsonb, '(A) Because the particle starts and finishes at the exact same location, its net position displacement is zero ($\Delta \vec{r} = 0$), making statement I true. Average speed is total distance over time, which is strictly greater than zero (II is false). Uniform circular motion features a continuous change in velocity direction, requiring a nonzero centripetal acceleration directed toward the center ($a_c = v^2/r \ne 0$) (III is false).'),
  ('ap-topic-physc-kinematics_q2', 'ap-topic-physc-kinematics', 2, false, 'C', 'Average Acceleration Vector Sum', 'medium', 'At time $t = t_1$, an object''s velocity is $\vec{v}_1$. A short time later, at $t = t_2$, its velocity is $\vec{v}_2$. If $|\vec{v}_1| = |\vec{v}_2|$, which vector best illustrates the average acceleration $\vec{a}_{\text{avg}}$ between $t_1$ and $t_2$?', '["Vector pointing along $\\vec{v}_1$","Vector pointing along $\\vec{v}_2$","Vector pointing downward and to the left (along $\\vec{v}_2 - \\vec{v}_1$)","Vector pointing upward","Zero vector"]'::jsonb, '(C) Average acceleration is defined by $\vec{a}_{\text{avg}} = \frac{\Delta\vec{v}}{\Delta t} = \frac{\vec{v}_2 - \vec{v}_1}{\Delta t} = \frac{\vec{v}_2 + (-\vec{v}_1)}{\Delta t}$. Vector addition of $\vec{v}_2$ and the inverted vector $-\vec{v}_1$ yields a resultant vector directed downward and to the left.'),
  ('ap-topic-physc-kinematics_q3', 'ap-topic-physc-kinematics', 3, false, 'C', '2D Projectile Acceleration', 'easy', 'A rock is thrown off a $30\text{-m}$ cliff at a $45^\circ$ angle above the horizontal. Which of the following is true regarding the acceleration of the rock? (Ignore air resistance)', '["The acceleration will have both horizontal and vertical components.","At the peak, acceleration is half of its initial launch value.","The acceleration will be of magnitude $g$ and in a downward direction.","The acceleration is downward on ascent and upward on descent.","The acceleration increases throughout the flight."]'::jsonb, '(C) Once in free-fall ballistic flight under negligible air resistance, the only force acting on the projectile is gravity ($F_g = mg$, downward). The acceleration is uniformly constant everywhere along the trajectory: $\vec{a} = -g\hat{j}$.'),
  ('ap-topic-physc-kinematics_q4', 'ap-topic-physc-kinematics', 4, false, 'C', 'Vertical Free Fall Acceleration at Apex', 'easy', 'A baseball is thrown straight upward. What is the ball''s acceleration at its highest point?', '["$0$","$-g$, downward","$g$, downward","$-g$, upward","$g$, upward"]'::jsonb, '(C) Even though the instantaneous velocity of the ball is zero at the apex of its path, the gravitational force continues to act on the ball without interruption, producing a constant downward acceleration of magnitude $g$.'),
  ('ap-topic-physc-kinematics_q5', 'ap-topic-physc-kinematics', 5, false, 'C', 'Calculus Kinematics & Max Velocity', 'medium', 'An object''s position is given by $x(t) = -3t^3 + t^2 + 6t$. What is the maximum velocity of the object?', '["$0.11\\text{ m/s}$","$2.73\\text{ m/s}$","$6.11\\text{ m/s}$","$7.39\\text{ m/s}$","$9.81\\text{ m/s}$"]'::jsonb, '(C) Velocity function:
  $$v(t) = \frac{dx}{dt} = -9t^2 + 2t + 6$$
To find the maximum velocity, set the derivative of velocity (acceleration) equal to zero:
  $$\frac{dv}{dt} = -18t + 2 = 0 \implies t = \frac{1}{9}\text{ s} \approx 0.111\text{ s}$$
Evaluate $v(t)$ at $t = 1/9\text{ s}$:
  $$v_{\max} = -9\left(\frac{1}{9}\right)^2 + 2\left(\frac{1}{9}\right) + 6 = -\frac{1}{9} + \frac{2}{9} + 6 = 6 + \frac{1}{9} \approx 6.11\text{ m/s}$$'),
  ('ap-topic-physc-kinematics_q6', 'ap-topic-physc-kinematics', 6, false, 'D', 'Free Fall Drop Height Calculation', 'easy', 'A rock dropped off a cliff strikes the ground with an impact speed of $30\text{ m/s}$. How high was the cliff? ($g = 10\text{ m/s}^2$)', '["$15\\text{ m}$","$20\\text{ m}$","$30\\text{ m}$","$45\\text{ m}$","$60\\text{ m}$"]'::jsonb, '(D) Using the kinematic equation $v_f^2 = v_0^2 + 2g\Delta y$ with $v_0 = 0$:
  $$\Delta y = \frac{v_f^2}{2g} = \frac{(30\text{ m/s})^2}{2(10\text{ m/s}^2)} = \frac{900}{20} = 45\text{ m}$$'),
  ('ap-topic-physc-kinematics_q7', 'ap-topic-physc-kinematics', 7, false, 'C', 'Horizontal Projectile Flight Time', 'easy', 'A stone is thrown horizontally with an initial speed of $10\text{ m/s}$ from a bridge. How long would it take to strike the water $80\text{ m}$ below the bridge? ($g = 10\text{ m/s}^2$)', '["$1\\text{ s}$","$2\\text{ s}$","$4\\text{ s}$","$8\\text{ s}$","$16\\text{ s}$"]'::jsonb, '(C) Vertical and horizontal motions are independent. With $v_{0y} = 0$:
  $$h = \frac{1}{2}gt^2 \implies t = \sqrt{\frac{2h}{g}} = \sqrt{\frac{2(80\text{ m})}{10\text{ m/s}^2}} = \sqrt{16} = 4\text{ s}$$'),
  ('ap-topic-physc-kinematics_q8', 'ap-topic-physc-kinematics', 8, false, 'B', 'Angled Projectile Total Hang Time', 'easy', 'A soccer ball at rest is kicked with initial velocity $10\text{ m/s}$ at launch angle $30^\circ$. Calculate its total flight time over level ground ($g = 10\text{ m/s}^2$).', '["$0.5\\text{ s}$","$1.0\\text{ s}$","$1.7\\text{ s}$","$2.0\\text{ s}$","$2.5\\text{ s}$"]'::jsonb, '(B) $$v_{0y} = v_0\sin(30^\circ) = 10(0.5) = 5\text{ m/s}$$
$$T = \frac{2v_{0y}}{g} = \frac{2(5\text{ m/s})}{10\text{ m/s}^2} = 1.0\text{ s}$$'),
  ('ap-topic-physc-kinematics_q9', 'ap-topic-physc-kinematics', 9, false, 'C', '2D Projectile Impact Speed', 'medium', 'A stone is thrown horizontally with initial speed $30\text{ m/s}$ from a bridge. Find the stone''s total speed when it enters the water $4\text{ s}$ later ($g = 10\text{ m/s}^2$).', '["$30\\text{ m/s}$","$40\\text{ m/s}$","$50\\text{ m/s}$","$60\\text{ m/s}$","$70\\text{ m/s}$"]'::jsonb, '(C) Horizontal velocity: $v_x = 30\text{ m/s}$ (constant).  
Vertical velocity: $v_y = gt = (10\text{ m/s}^2)(4\text{ s}) = 40\text{ m/s}$.  
Magnitude: $v = \sqrt{v_x^2 + v_y^2} = \sqrt{30^2 + 40^2} = 50\text{ m/s}$.'),
  ('ap-topic-physc-kinematics_q10', 'ap-topic-physc-kinematics', 10, false, 'E', 'Projectile Motion Vertical vs Horizontal Velocity', 'easy', 'Which statement is true concerning the motion of an ideal projectile launched at $45^\circ$?', '["The acceleration vector points opposite to velocity on ascent and along velocity on descent.","The speed at the top of the trajectory is zero.","Total speed remains constant throughout.","Horizontal speed decreases ascending and increases descending.","Vertical speed decreases on the way up and increases on the way down."]'::jsonb, '(E) Because the downward gravitational acceleration opposes upward vertical velocity during ascent, vertical speed $|v_y|$ decreases to zero at the apex, then increases continuously as the projectile falls. Horizontal speed remains strictly constant throughout.'),
  ('ap-topic-physc-kinematics_q11', 'ap-topic-physc-kinematics', 11, false, 'A', 'Trajectory Equation & Wall Clearance Angle', 'hard', 'An object is launched from the ground with speed $v$ at distance $d$ away from a wall of height $h$. Which equation gives the launch angle $\theta$ to just clear the wall?', '["$h = d\\tan\\theta - \\frac{gd^2}{2v^2\\cos^2\\theta}$","$h = d^2\\cos\\theta - \\frac{gd^2}{2v^2\\cos^2\\theta}$","$h = d\\tan\\theta - \\frac{gd^2}{2v\\cos\\theta}$","$h = d\\sin\\theta - \\frac{gd^2}{v^2\\cos^2\\theta}$","$h = d\\sin\\theta - \\frac{gd^2}{2v\\cos\\theta}$"]'::jsonb, '(A) Horizontal time to reach the wall: $t = \frac{d}{v\cos\theta}$.
Substituting into vertical position $y(t) = (v\sin\theta)t - \frac{1}{2}gt^2$:
  $$h = (v\sin\theta)\left(\frac{d}{v\cos\theta}\right) - \frac{1}{2}g\left(\frac{d}{v\cos\theta}\right)^2 = d\tan\theta - \frac{gd^2}{2v^2\cos^2\theta}$$'),
  ('ap-topic-physc-kinematics_q12', 'ap-topic-physc-kinematics', 12, false, 'D', 'Velocity-Time Graph & Position Integral', 'medium', 'An object moves in a straight line with a given velocity-time graph. If $x = 3.0\text{ m}$ at $t = 0$, what is the position at $t = 3.0\text{ s}$ if the area under the $v\text{--}t$ curve from $0$ to $3\text{ s}$ is $8\text{ m}$?', '["$5\\text{ m}$","$8\\text{ m}$","$10\\text{ m}$","$11\\text{ m}$","$14\\text{ m}$"]'::jsonb, '(D) Displacement is the definite integral of velocity: $\Delta x = \int_0^3 v(t)\,dt = 8\text{ m}$.
  $$x(3) = x(0) + \Delta x = 3.0\text{ m} + 8\text{ m} = 11\text{ m}$$'),
  ('ap-topic-physc-electrostatics_q1', 'ap-topic-physc-electrostatics', 1, false, 'C', 'Ch10: Electrostatics', 'medium', 'Two experiments are performed using a pair of solid metal spheres connected by a switch, as shown in Figure 10.9. Both spheres are grounded before each experiment so that they initially have no charge. Figure 10.9 Experiment I: A positively charged rod is brought near sphere A while the switch is closed, the switch is opened, and the rod is then removed. Experiment II: A positively charged rod is touched to sphere A while the switch is closed, the switch is opened, and the rod is then removed. Which of the following describes the charge on the spheres after the two experiments?', '["After experiment I both spheres have no charge; after experiment II both spheres are positively charged.","After experiment I sphere A is negatively charged and sphere B is positively charged; after experiment II sphere A is positively charged and sphere B is negatively charged.","After experiment I sphere A is negatively charged and sphere B is positively charged; after experiment II both spheres are positively charged.","After both experiments, both spheres are positively charged.","After both experiments, sphere A is positively charged and sphere B is negatively charged."]'::jsonb, '(C) Experiment I involves electrostatic induction. When the positively charged rod is brought near sphere A, it attracts electrons from both spheres, causing sphere A to have a slight negative charge and sphere B to have a slight positive charge. Because the switch is opened before the rod is removed, the charge never has a chance to redistribute itself, so after the experiment is over, sphere A is left negatively charged and sphere B is left positively charged. Experiment II involves conduction. The rod removes a large negative charge from the two-sphere system, leaving both spheres with a large net positive charge. Although induction effects cause the positive charge on sphere B to be slightly larger than the charge on sphere A, in general conduction imparts a much greater charge than induction, so the net charge of both spheres after the switch is opened is positive. Note that choice (D) can be immediately eliminated by conservation of charge. Because the rod never touches the sphere system in experiment I, the amount of charge on the two spheres together must remain constant; it is impossible for both to have a positive or a negative charge at any point during or after experiment I.'),
  ('ap-topic-physc-electrostatics_q2', 'ap-topic-physc-electrostatics', 2, false, 'C', 'Ch10: Electrostatics', 'medium', 'Two identical conducting spheres A and B are mounted on insulating stands. Initially, sphere A carries positive charge +Q and sphere B is uncharged. The two spheres are brought into contact, allowed to reach equilibrium, and then separated. What is the final charge on sphere A?', '["Zero","+Q / 4","+Q / 2","+Q","+2Q"]'::jsonb, 'When two identical conducting spheres touch, charge redistributes equally between them to equalize their electric potentials. The total initial charge is Q_total = +Q + 0 = +Q. By symmetry, the charge divides equally: Q_A = Q_B = Q_total / 2 = +Q/2.'),
  ('ap-topic-physc-electrostatics_q3', 'ap-topic-physc-electrostatics', 3, false, 'B', 'Ch10: Electrostatics', 'medium', 'Which of the three distributions in Figure 10.10 has a point or points where the potential is zero (excluding \pm \infty but assuming that the potential equals zero at these latter points)? Figure 10.10', '["distribution I only","distribution II only","distribution III only","distributions I and II, only","distributions I, II, and III"]'::jsonb, '(B) For any distribution of two point charges, the charges must have opposite signs for there to be a location(s) where the potential is zero. (Otherwise, both charges will never be able to cancel out each other’s contribution.) In distribution II, the potential is zero in between the two charges, much closer to the −q charge because this charge has a smaller magnitude (which can be compensated for by having a greater 1/r term in its potential contribution), and also to the left of the −q charge. This behavior is illustrated in Figure 10.17, which shows the potential due to point charges. Figure 10.17'),
  ('ap-topic-physc-electrostatics_q4', 'ap-topic-physc-electrostatics', 4, false, 'B', 'Ch10: Electrostatics', 'medium', 'Two point charges +4q and -q are fixed on the x-axis at x = 0 and x = d, respectively. At what finite position on the x-axis is the net electric field equal to zero?', '["x = d / 2","x = 2d","x = -d","x = 3d","There is no point on the x-axis where the field is zero"]'::jsonb, 'For the net field to be zero, the electric fields of the two opposite charges must point in opposite directions and have equal magnitudes. Between x = 0 and x = d, both fields point in the +x direction (no cancellation). To the left of x = 0 (x < 0), the larger charge +4q is always closer than -q, so its field always dominates. To the right of -q (x > d), the fields point in opposite directions. Setting magnitudes equal: k(4q)/x^2 = k(q)/(x - d)^2 ==> 2/x = 1/(x - d) ==> 2x - 2d = x ==> x = 2d.'),
  ('ap-topic-physc-electrostatics_q5', 'ap-topic-physc-electrostatics', 5, false, 'B', 'Ch10: Electrostatics', 'medium', 'Consider the potential vs position function shown in Figure 10.11 (the potential asymptotically approaches zero as x goes to + infinity or − infinity). At which of the points—A, B, C, D, or E—does a positive charge feel the greatest force in the +x-direction? Figure 10.11', '["point A","point B","point C","point D","point E"]'::jsonb, '(B) The electric field is the negative slope of the potential curve, Ex = −dV/dx, so the place where the force to the right (the positive force) is maximized is the place where the slope of the potential curve has a negative value with the greatest magnitude, at point B.'),
  ('ap-topic-physc-electrostatics_q6', 'ap-topic-physc-electrostatics', 6, false, 'B', 'Ch10: Electrostatics', 'medium', 'The electric potential V in a region of space depends only on the x-coordinate and is given by V(x) = 4x^2 - 3x + 2, where V is in volts and x is in meters. What is the x-component of the electric field at x = 2.0 m?', '["+13 N/C","-13 N/C","+16 N/C","-8 N/C","+8 N/C"]'::jsonb, 'The relationship between electric field and electric potential in one dimension is E_x = -dV/dx. Differentiating V(x): dV/dx = d/dx (4x^2 - 3x + 2) = 8x - 3. At x = 2.0 m: dV/dx = 8(2.0) - 3 = 13 V/m. Therefore, E_x = -13 V/m (or -13 N/C).'),
  ('ap-topic-physc-electrostatics_q7', 'ap-topic-physc-electrostatics', 7, false, 'C', 'Ch10: Electrostatics', 'medium', 'In the five charge distributions shown in Figure 10.12, all have identical square geometry and all charges have identical magnitudes q. In how many of the charge distributions is the electric field zero at the center of the square? Figure 10.12', '["one","two","three","four","five"]'::jsonb, '(C) Because of symmetry, distributions (b), (d), and (e) all have an electric field of zero at the center of the square. Said another way: If we pair charges along the diagonals of the square, we will see that in distributions (b), (d), and (e), each pair consists of two charges of the same sign and hence produce a net field of zero at the center of the square.'),
  ('ap-topic-physc-electrostatics_q8', 'ap-topic-physc-electrostatics', 8, false, 'C', 'Ch10: Electrostatics', 'medium', 'Four point charges of equal magnitude Q are placed at the four corners of a square of side length a. Two opposite corners have positive charges +Q, and the other two opposite corners have negative charges -Q. What is the net electric potential V at the center of the square (taking V = 0 at infinity)?', '["4 k Q / a","2 sqrt(2) k Q / a","Zero","-2 sqrt(2) k Q / a","sqrt(2) k Q / a"]'::jsonb, 'Electric potential is a scalar quantity given by V = sum (k q_i / r_i). The center of the square is equidistant from all four corners, at distance r = (a sqrt(2)) / 2 = a / sqrt(2). The total potential at the center is V = k/r * (+Q + Q - Q - Q) = k/r * (0) = 0.'),
  ('ap-topic-physc-electrostatics_q9', 'ap-topic-physc-electrostatics', 9, false, 'B', 'Ch10: Electrostatics', 'medium', 'The axis of the cone in Figure 10.13 lies on the y-axis. The cone has a uniform charge density. Based on symmetry considerations alone, in what direction(s) can the electric field at the origin point? (The origin lies within the cone along its axis of symmetry.) Figure 10.13', '["the x-axis","the y-axis","the z-axis","anywhere along the xy-plane","anywhere along the yz-plane"]'::jsonb, '(B) Imagine describing to a friend what direction the electric field points; the only description you could give would be “toward the tip of the cone” or “away from the tip of the cone” (i.e., along the y-axis).'),
  ('ap-topic-physc-electrostatics_q10', 'ap-topic-physc-electrostatics', 10, false, 'B', 'Ch10: Electrostatics', 'medium', 'A thin non-conducting rod of length L carries a uniformly distributed positive charge Q. Which of the following correctly expresses the electric potential V at a point P located on the perpendicular bisector of the rod at a distance y from its center (taking V = 0 at infinity)?', '["V is proportional to 1 / y^2","V = (k Q / L) * ln( (sqrt((L/2)^2 + y^2) + L/2) / (sqrt((L/2)^2 + y^2) - L/2) )","V = k Q / y","V is zero due to symmetry","V = k Q / (y^2 + (L/2)^2)"]'::jsonb, 'Let the rod lie along the x-axis from x = -L/2 to x = +L/2 with linear charge density lambda = Q/L. An infinitesimal element dx at position x carries charge dq = lambda dx and is at distance r = sqrt(x^2 + y^2) from point (0, y). The potential is V = int k dq / r = (k Q / L) int_{-L/2}^{L/2} dx / sqrt(x^2 + y^2) = (k Q / L) * [ln(x + sqrt(x^2 + y^2))]_{-L/2}^{L/2} = (k Q / L) * ln( (sqrt((L/2)^2 + y^2) + L/2) / (sqrt((L/2)^2 + y^2) - L/2) ).'),
  ('ap-topic-physc-electrostatics_q11', 'ap-topic-physc-electrostatics', 11, false, 'C', 'Ch10: Electrostatics', 'medium', 'Which of the following statements is true regarding the value of the electric field and the potential along a line passing perpendicularly through an infinite planar charge distribution (with uniform surface charge density)?', '["The potential and the electric field are discontinuous.","The potential and the electric field are continuous.","The potential is continuous, and the electric field is discontinuous.","The potential is discontinuous, and the electric field is continuous.","The continuity of the potential and electric fields depend on the sign of the charge."]'::jsonb, '(C) Figure 10.18 shows the behavior of the electric field and the potential along the x-axis due to a constant positive surface charge density along the yz-plane. The electric field due to an infinite planar charge distribution has magnitude E = \sigma/2\epsilon0 whose direction abruptly changes as the point passes through the planar charge distribution (making the electric field discontinuous at this point). Because the electric field is equal to the negative slope of the potential along the x- axis, this implies that the potential’s slope is discontinuous at x = 0 but the potential itself is continuous. Changing the sign of the charge switches the sign of the electric field and potential but does not affect whether they are continuous or discontinuous. Figure 10.18'),
  ('ap-topic-physc-electrostatics_q12', 'ap-topic-physc-electrostatics', 12, false, 'C', 'Ch10: Electrostatics', 'medium', 'A thin semicircular plastic rod of radius R carries a uniformly distributed positive charge +Q. What is the magnitude of the electric field at the center of curvature O of the semicircle?', '["Zero","k Q / R^2","2 k Q / (pi R^2)","k Q / (2 pi R^2)","4 k Q / (pi^2 R^2)"]'::jsonb, 'By symmetry, the components of the electric field parallel to the diameter of the semicircle cancel out. The perpendicular components add up: dE_perp = (k dq / R^2) * cos(theta), where dq = lambda R dtheta = (Q / (pi R)) R dtheta = (Q / pi) dtheta. Integrating from theta = -pi/2 to +pi/2: E = int_{-pi/2}^{pi/2} (k (Q/pi) cos(theta) dtheta) / R^2 = (k Q / (pi R^2)) [sin(theta)]_{-pi/2}^{pi/2} = (k Q / (pi R^2)) * (1 - (-1)) = 2 k Q / (pi R^2).'),
  ('ap-topic-physc-electrostatics_q13', 'ap-topic-physc-electrostatics', 13, false, 'B', 'Ch10: Electrostatics', 'medium', 'A point charge +q is placed at distance d from an infinite, grounded, planar conducting sheet. By the method of images, what is the magnitude and direction of the force exerted on the charge +q by the induced surface charges on the sheet?', '["Zero","k q^2 / (4 d^2) toward the sheet","k q^2 / (4 d^2) away from the sheet","k q^2 / (2 d^2) toward the sheet","k q^2 / d^2 toward the sheet"]'::jsonb, 'By the method of images, the boundary condition V = 0 on the grounded conducting sheet is equivalent to placing an image charge of -q at distance d behind the plane (a total separation of 2d from the real charge +q). The electrostatic force on +q is attractive (toward the sheet) with magnitude F = k |q(-q)| / (2d)^2 = k q^2 / (4 d^2).'),
  ('ap-topic-physc-electrostatics_q14', 'ap-topic-physc-electrostatics', 14, false, 'B', 'Ch10: Electrostatics', 'medium', 'Two concentric conducting spherical shells have radii a and b (with a < b). The inner shell carries net charge +Q and the outer shell carries net charge -Q. What is the electric potential difference Delta V = V(a) - V(b) between the two shells?', '["Zero","(k Q) * (1/a - 1/b)","(k Q) * (1/b - 1/a)","k Q / (b - a)","(k Q) / (a + b)"]'::jsonb, 'In the region between the shells (a <= r <= b), Gauss''s law gives the radial electric field E(r) = k Q / r^2. The potential difference is Delta V = V(a) - V(b) = - int_b^a E(r) dr = int_a^b (k Q / r^2) dr = k Q [-1/r]_a^b = k Q (1/a - 1/b).'),
  ('ap-topic-physc-electrostatics_q15', 'ap-topic-physc-electrostatics', 15, false, 'B', 'Ch10: Electrostatics', 'medium', 'Three nonconducting spheres all have the same net charge +Q and radius R. The charge is uniformly distributed throughout the volume of sphere A, uniformly distributed on the surface of sphere B, and distributed with a density proportional to the radial variable, \rho = cr throughout the volume of sphere C (c = Q/\piR4). Which of the following is a valid comparison of the potentials at the centers of each of the spheres?', '["VA > VB > VC","VA > VC > VB","VC > VA > VB","VC > VB > VA","VB = VC = VA Free-Response Questions"]'::jsonb, '(B) Although the field (and thus the potential) is identical outside the spheres, this is not the case inside the spheres. The spheres all have the same net charge. Therefore, based on the equation for potential, V = \int dQ/4\pir\epsilon0, the closer the charge is to the center of the sphere, the greater the potential is at the center of the sphere. Sphere B, with all the charge on the surface of the sphere, has its charge located farthest away from the center of the sphere and therefore has the lowest potential [eliminating all choices except (B) and (C)]. Sphere C, with a charge density proportional to its distance from the sphere, tends to distribute more charge at a larger r, farther from the center of the sphere, compared to sphere A. Therefore, VC < VA and the correct answer is choice (B). Free-Response 1. (a) See Figure 10.19. Symmetry considerations dictate that the direction of the electric field for points on the x-axis is parallel to the x-axis. (You can also see this by noting that the y-components of the electric fields due to the two point charges exactly cancel each other at these points.) Both point charges +Q make equal contributions to Ex: Figure 10.19 This result makes sense. At x = 0, the electric field is zero (because of symmetry). As x \to  \infty, x >> a, so that x2 + a2 \approx  x2 and the electric field is approximately given by , the same as the electric field due to a charge of +2Q at the origin. (As you move farther and farther along the x-axis, the separation between the two charges becomes negligible and all you can “see” is one effective charge equal to +2Q.) (b) Using the definition of electric field, the force is obtained by multiplying the electric field by the charge: (c) Calculating potential using the equation V = ∑(Qi/4\pi\epsilon0ri) yields 2. (a) and (b) Consider Figures 10.20 and 10.21. The key point here is to use superposition. Graph the field and potential due to one charge, graph the field and voltage due to the other charge, and then sum the graphs. Thus, superposition reduces the two-charge problem to two one-charge problems, allowing you to worry about only one charge at a time. (c) The force is zero; the forces due to each point charge cancel each other. (From the sketch of the electric field, you can see that the field at the origin is zero.) (d) Use conservation of energy: Electrical potential energy is converted to kinetic energy: Figure 10.20 Figure 10.21 3. (a) See Example 8.3. When a mass hangs vertically, gravity determines the equilibrium height of the mass. If the mass is pulled 5.0 cm below the equilibrium point and released from rest, it will oscillate as high as 5.0 cm above the equilibrium point, corresponding to a point 15.0 cm above the table. (b) As discussed in Example 8.3, the angular frequency of oscillation is given by the usual formula for a mass oscillating along a horizontal line. Thus, . (c) We choose +y downward and set y = 0 at the equilibrium position of the charge. Then from Chapter 8 we know that y = (5.0 cm) cos \omegat for a mass released from rest 5.0 cm below (i.e., positive y) equilibrium. The equilibrium point is 10.0 cm above the table; thus, the height of the charge above the table is given by h = 10.0 cm − (5.0 cm) cos \omegat. You can check the minus sign on the right-hand side by plugging in t = 0 s to obtain h = 5.0 cm, the initial height of the charge. (d) The magnitude of the electric field at point P is given by The field is directed away from the positive charge Q, i.e, it points downward at P. (e) The potential of the point charge Q at point P is given by: 4. (a) Along the +x-axis, symmetry dictates that the field must point in the x-direction. Summing the contributions of the x-components of the electric fields due to the three point charges yields the following (the vector geometry is the same as in question 1). (b) Applying the equation V = ∑(Qi/4\pi\epsilon0ri), (c) For very small x, we can make the following two approximations: (1) x2 + a2 \approx  a2; therefore, (2) 1/x2 >> x; therefore, This is the electric field due to a point charge −Q at the origin. Thus, when x is very small, the fields due to the two positive charges nearly cancel, and the dominant effect is due to the −Q at the origin (which exerts a strong field because it is so close to point x). (d) For very large x, we can make the approximation x2 + a2 \approx  x2. Therefore, This is the electric field due to a charge +Q at the origin. When you are very far from the origin, it’s impossible to see the separation of the three charges—it seems that they’re all at the origin. The resulting field is due to the sum of the three charges, Qeffective = Q + Q − Q = Q, at the origin. 5. (a) See Figure 10.22. We have a linear charge distribution and thus use differential line segments of length dx. The charge density is given by \lambda = Q / (2ℓ) and is positive. A point on the y-axis located at (0, y) is a distance r from a differential line segment dx located at x where . Thus, the potential is given by the integral: where we did the integral using the substitution x = y tan \theta. Figure 10.22 (b) As y approaches infinity, the argument of the logarithm approaches 1 and thus the potential goes to 0. This is to be expected as we chose, in general, to have the potential 0 at infinity. (c) As y approaches 0, the potential diverges, not surprisingly, as we are approaching the charge distribution. In Example 10.1, the rod did not overlap the origin, so we obtained a finite answer for the potential at the origin given by The rod would overlap the origin if a < 0 and b > 0, in which case V would diverge. (d) Because the rod has uniformly distributed charge and is centered at the origin, we know by symmetry that the electric field must be parallel to the y-axis. The rod has positive charge, and thus the field points away from the rod. If the y-axis is vertical, then the field points up for y > 0 and down for y < 0. 6. (a) All the charge is the same distance from the origin, so the potential is simply: The charge Q is obtained by multiplying the length by the linear charge density (recall that arc length = r\theta). Substituting, (b) According to symmetry, the only uniquely defined direction at the origin is the horizontal direction, so any nonzero net field must point in this direction. We calculate the field by dividing the arc into differential arc legnths dl = ad\theta and summing the x-component of the electric field due to each differential arc length as shown in Figure 10.23. Figure 10.23 As in part (a), the differential charge is obtained by multiplying the arc length by the linear charge density: Substituting for dQ, Integrating, and (c) From the potential calculated in part (a), Because the potential is proportional to ϕ, it is maximized when ϕ is maximized, at ϕ = \pi (creating a complete circular ring of charge). (d) From the electric field calculated in part (b), The potential is maximized when sinϕ is maximized, at ϕ = \pi/2 (creating an exact seimicircle of charge). Answer check for parts (c) and (d): Although the math immediately gave us the answers, we could have figured out the answers simply based on physics. As for the potential, the more charge there is nearby, the higher the potential. Therefore, the potential is maximized when the charge is maximum, which occurs when the entire ring contains charge. As for the electric field, symmetry always requires the net field to be in the x-direction. Therefore, the magnitude of the field is equal to the x- component. Now let’s consider a few extreme situations: (i) ϕ = 0, no charge, no electric field; (ii) ϕ = \pi/2, semicircle of charge, electric field in the +x-direction; (iii) ϕ = \pi, circle of charge, symmetry requires that electric field is zero. Clearly, the maximal charge lies somewhere between ϕ = 0 and ϕ = \pi. Now let’s think about how the field changes as ϕ increases from zero to \pi. As ϕ increases from 0 to \pi/2, matching differential regions above and below the x-axis produces a net field in the positive x-direction, causing the electric field to increase. However, as ϕ increases beyond \pi/2, matching differential regions above and below the x-axis causes a field in the negative x-direction, causing the total field to shrink back to zero. Thus, calculating extrema from the first derivative, the maximum must lie where the field is about to stop growing and start decreasing, at \pi/2. (e) Again, all the charge is the same distance from the origin: (f) Same as in part (b), except that we must use the substitution \lambda = Q/l = Q/2aϕ: (g) Potential doesn’t depend on ϕ, so it is maximized for any value of ϕ. (h) When ϕ is very small (ϕ \approx  0), all the charge is concentrated at (−a, 0), and it acts like a point charge. In this situation, all the differential electric fields due to differential bits of charge point along the x-axis, and there is no cancellation. As ϕ increases, the charge is spread around the circle, causing the differential charges to produce differential electric fields with components in the y-direction that cancel each other. This cancellation “wastes” electric field, decreasing the field to the point where the field equals zero when ϕ = \pi. Therefore, the field is maximized when ϕ = 0.'),
  ('ap-topic-physc-electrostatics_q16', 'ap-topic-physc-electrostatics', 16, false, 'A', 'Diagnostic Test – E&M', 'medium', 'A solid insulating sphere of radius R has a uniform volume charge density rho. Using Gauss''s law, what is the electric field magnitude E(r) as a function of distance r from the center of the sphere for r < R?', '["rho r / (3 epsilon_0)","rho R / (3 epsilon_0)","rho r^2 / (3 epsilon_0 R)","rho / (3 epsilon_0 r^2)","Zero"]'::jsonb, 'Consider a spherical Gaussian surface of radius r < R. The enclosed charge is q_enc = rho * (4/3 pi r^3). By Gauss''s Law: oint E * dA = E * (4 pi r^2) = q_enc / epsilon_0 = (4/3 pi rho r^3) / epsilon_0 ==> E(r) = rho r / (3 epsilon_0). The field increases linearly with distance r from the center.'),
  ('ap-topic-physc-electrostatics_q17', 'ap-topic-physc-electrostatics', 17, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A charged particle is launched into a region of uniform magnetic field. Given that the particle’s initial velocity has components parallel and perpendicular to the magnetic field, describe the particle’s path qualitatively.', '["a straight line","a circle","a helical (corkscrew) path","a parabolic path","none of the above"]'::jsonb, '(C) See the discussion of the motion of particles within magnetic fields in Chapter 14.'),
  ('ap-topic-physc-electrostatics_q18', 'ap-topic-physc-electrostatics', 18, false, 'B', 'Diagnostic Test – E&M', 'medium', 'A point charge +Q is located at a fixed distance from a sphere. Compare the magnitude of the attractive force on the sphere if the sphere is (1) metal with net charge −Q, (2) metal with no net charge, (3) an insulator with net charge −Q, or (4) an insulator with no net charge.', '["charged metal = charged insulator > uncharged metal = uncharged insulator","charged metal > charged insulator > uncharged metal > uncharged insulator","charged insulator > charged metal > uncharged insulator > uncharged metal","charged insulator > charged metal > uncharged metal = uncharged insulator","charged insulator = charged metal > uncharged metal > uncharged insulator"]'::jsonb, '(B) This is a question about electrostatic induction. When a positive point charge is placed near a metal sphere (charged or uncharged), it attracts mobile electrons in the metal, causing the metal to become polarized such that more negative charge is on the side closer to the positive point charge and more positive charge is on the side farther away from the positive point charge. Because this charge redistribution results in moving negative charge closer to the positive point charge and moving positive charge farther away from the positive point charge, it increases the attractive force between the metal sphere and the positive point charge. Therefore, compared to an insulating sphere with the same net charge, a metal sphere always experiences a greater attractive force (such that charged metal > charged insulator and uncharged metal > uncharged insulator). Because this inductive effect is small compared to the effect of actually putting net charge −Q on the sphere, charged insulator > uncharged metal.'),
  ('ap-topic-physc-electrostatics_q19', 'ap-topic-physc-electrostatics', 19, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A bar moves to the right through a magnetic field as shown (the magnetic field points into the page). What is the potential difference between points A and B after equilibrium is established in the bar?', '["The difference is v2Bd, with A at higher potential.","The difference is v2Bd, with B at higher potential.","The difference is vBd, with A at higher potential.","The difference is vBd, with B at higher potential.","Because there is no loop, there is no flux, so there is no potential difference."]'::jsonb, '(C) The charges within the bar are moving in a magnetic field, so they feel a magnetic force. Using the conventional-current description, positive charges feel an upward force, causing positive charge to accumulate at the top end of the bar (leaving negative charge on the bottom end of the bar). This charge continues to accumulate until the electric force created by the charge imbalance cancels the magnetic force, mathematically qE = qvB. The magnitude of the potential difference between points A and B is then |V | = |−\int E \cdot  dr| = |vBd|. The electric field points down (producing a force that opposes the magnetic force), and recalling that electric fields point from high to low potential, we see that point A is at the higher potential. Further information about motional EMF can be found in Example 15.6.'),
  ('ap-topic-physc-electrostatics_q20', 'ap-topic-physc-electrostatics', 20, false, 'B', 'Diagnostic Test – E&M', 'medium', 'Suppose that the electric potential in a region of space is a constant. What can you conclude about the magnitude of the electric field in this region?', '["It is a nonzero constant.","It is zero.","It is proportional to the distance from the origin.","It is given by","Not enough information is given. Questions 6–8 refer to a circular region of radius a with a uniform magnetic field pointing into the page that is increasing at a constant rate as shown. A circular loop of wire of radius r is centered on the middle of the region."]'::jsonb, '(B) The electric field is the negative derivative (with respect to the spatial coordinate) of the potential. Thus, with a constant potential the electric field must be zero.'),
  ('ap-topic-physc-kinematics-forces-energy_q1', 'ap-topic-physc-kinematics-forces-energy', 1, false, 'A', 'Uniform Circular Motion & Kinematics', 'easy', 'An object that''s moving with constant speed travels once around a circular path. Which of the following is/are true concerning this motion?  I. The displacement is zero.  II. The average speed is zero.  III. The acceleration is zero.', '["I only","I and II only","I and III only","III only","II and III only"]'::jsonb, '(A) Because the particle starts and finishes at the exact same location, its net position displacement is zero ($\Delta \vec{r} = 0$), making statement I true. Average speed is total distance over time, which is strictly greater than zero (II is false). Uniform circular motion features a continuous change in velocity direction, requiring a nonzero centripetal acceleration directed toward the center ($a_c = v^2/r \ne 0$) (III is false).'),
  ('ap-topic-physc-kinematics-forces-energy_q2', 'ap-topic-physc-kinematics-forces-energy', 2, false, 'C', 'Average Acceleration Vector Sum', 'medium', 'At time $t = t_1$, an object''s velocity is $\vec{v}_1$. A short time later, at $t = t_2$, its velocity is $\vec{v}_2$. If $|\vec{v}_1| = |\vec{v}_2|$, which vector best illustrates the average acceleration $\vec{a}_{\text{avg}}$ between $t_1$ and $t_2$?', '["Vector pointing along $\\vec{v}_1$","Vector pointing along $\\vec{v}_2$","Vector pointing downward and to the left (along $\\vec{v}_2 - \\vec{v}_1$)","Vector pointing upward","Zero vector"]'::jsonb, '(C) Average acceleration is defined by $\vec{a}_{\text{avg}} = \frac{\Delta\vec{v}}{\Delta t} = \frac{\vec{v}_2 - \vec{v}_1}{\Delta t} = \frac{\vec{v}_2 + (-\vec{v}_1)}{\Delta t}$. Vector addition of $\vec{v}_2$ and the inverted vector $-\vec{v}_1$ yields a resultant vector directed downward and to the left.'),
  ('ap-topic-physc-kinematics-forces-energy_q3', 'ap-topic-physc-kinematics-forces-energy', 3, false, 'C', '2D Projectile Acceleration', 'easy', 'A rock is thrown off a $30\text{-m}$ cliff at a $45^\circ$ angle above the horizontal. Which of the following is true regarding the acceleration of the rock? (Ignore air resistance)', '["The acceleration will have both horizontal and vertical components.","At the peak, acceleration is half of its initial launch value.","The acceleration will be of magnitude $g$ and in a downward direction.","The acceleration is downward on ascent and upward on descent.","The acceleration increases throughout the flight."]'::jsonb, '(C) Once in free-fall ballistic flight under negligible air resistance, the only force acting on the projectile is gravity ($F_g = mg$, downward). The acceleration is uniformly constant everywhere along the trajectory: $\vec{a} = -g\hat{j}$.'),
  ('ap-topic-physc-kinematics-forces-energy_q4', 'ap-topic-physc-kinematics-forces-energy', 4, false, 'C', 'Vertical Free Fall Acceleration at Apex', 'easy', 'A baseball is thrown straight upward. What is the ball''s acceleration at its highest point?', '["$0$","$-g$, downward","$g$, downward","$-g$, upward","$g$, upward"]'::jsonb, '(C) Even though the instantaneous velocity of the ball is zero at the apex of its path, the gravitational force continues to act on the ball without interruption, producing a constant downward acceleration of magnitude $g$.'),
  ('ap-topic-physc-kinematics-forces-energy_q5', 'ap-topic-physc-kinematics-forces-energy', 5, false, 'C', 'Calculus Kinematics & Max Velocity', 'medium', 'An object''s position is given by $x(t) = -3t^3 + t^2 + 6t$. What is the maximum velocity of the object?', '["$0.11\\text{ m/s}$","$2.73\\text{ m/s}$","$6.11\\text{ m/s}$","$7.39\\text{ m/s}$","$9.81\\text{ m/s}$"]'::jsonb, '(C) Velocity function:
  $$v(t) = \frac{dx}{dt} = -9t^2 + 2t + 6$$
To find the maximum velocity, set the derivative of velocity (acceleration) equal to zero:
  $$\frac{dv}{dt} = -18t + 2 = 0 \implies t = \frac{1}{9}\text{ s} \approx 0.111\text{ s}$$
Evaluate $v(t)$ at $t = 1/9\text{ s}$:
  $$v_{\max} = -9\left(\frac{1}{9}\right)^2 + 2\left(\frac{1}{9}\right) + 6 = -\frac{1}{9} + \frac{2}{9} + 6 = 6 + \frac{1}{9} \approx 6.11\text{ m/s}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q6', 'ap-topic-physc-kinematics-forces-energy', 6, false, 'D', 'Free Fall Drop Height Calculation', 'easy', 'A rock dropped off a cliff strikes the ground with an impact speed of $30\text{ m/s}$. How high was the cliff? ($g = 10\text{ m/s}^2$)', '["$15\\text{ m}$","$20\\text{ m}$","$30\\text{ m}$","$45\\text{ m}$","$60\\text{ m}$"]'::jsonb, '(D) Using the kinematic equation $v_f^2 = v_0^2 + 2g\Delta y$ with $v_0 = 0$:
  $$\Delta y = \frac{v_f^2}{2g} = \frac{(30\text{ m/s})^2}{2(10\text{ m/s}^2)} = \frac{900}{20} = 45\text{ m}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q7', 'ap-topic-physc-kinematics-forces-energy', 7, false, 'C', 'Horizontal Projectile Flight Time', 'easy', 'A stone is thrown horizontally with an initial speed of $10\text{ m/s}$ from a bridge. How long would it take to strike the water $80\text{ m}$ below the bridge? ($g = 10\text{ m/s}^2$)', '["$1\\text{ s}$","$2\\text{ s}$","$4\\text{ s}$","$8\\text{ s}$","$16\\text{ s}$"]'::jsonb, '(C) Vertical and horizontal motions are independent. With $v_{0y} = 0$:
  $$h = \frac{1}{2}gt^2 \implies t = \sqrt{\frac{2h}{g}} = \sqrt{\frac{2(80\text{ m})}{10\text{ m/s}^2}} = \sqrt{16} = 4\text{ s}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q8', 'ap-topic-physc-kinematics-forces-energy', 8, false, 'B', 'Angled Projectile Total Hang Time', 'easy', 'A soccer ball at rest is kicked with initial velocity $10\text{ m/s}$ at launch angle $30^\circ$. Calculate its total flight time over level ground ($g = 10\text{ m/s}^2$).', '["$0.5\\text{ s}$","$1.0\\text{ s}$","$1.7\\text{ s}$","$2.0\\text{ s}$","$2.5\\text{ s}$"]'::jsonb, '(B) $$v_{0y} = v_0\sin(30^\circ) = 10(0.5) = 5\text{ m/s}$$
$$T = \frac{2v_{0y}}{g} = \frac{2(5\text{ m/s})}{10\text{ m/s}^2} = 1.0\text{ s}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q9', 'ap-topic-physc-kinematics-forces-energy', 9, false, 'C', '2D Projectile Impact Speed', 'medium', 'A stone is thrown horizontally with initial speed $30\text{ m/s}$ from a bridge. Find the stone''s total speed when it enters the water $4\text{ s}$ later ($g = 10\text{ m/s}^2$).', '["$30\\text{ m/s}$","$40\\text{ m/s}$","$50\\text{ m/s}$","$60\\text{ m/s}$","$70\\text{ m/s}$"]'::jsonb, '(C) Horizontal velocity: $v_x = 30\text{ m/s}$ (constant).  
Vertical velocity: $v_y = gt = (10\text{ m/s}^2)(4\text{ s}) = 40\text{ m/s}$.  
Magnitude: $v = \sqrt{v_x^2 + v_y^2} = \sqrt{30^2 + 40^2} = 50\text{ m/s}$.'),
  ('ap-topic-physc-kinematics-forces-energy_q10', 'ap-topic-physc-kinematics-forces-energy', 10, false, 'E', 'Projectile Motion Vertical vs Horizontal Velocity', 'easy', 'Which statement is true concerning the motion of an ideal projectile launched at $45^\circ$?', '["The acceleration vector points opposite to velocity on ascent and along velocity on descent.","The speed at the top of the trajectory is zero.","Total speed remains constant throughout.","Horizontal speed decreases ascending and increases descending.","Vertical speed decreases on the way up and increases on the way down."]'::jsonb, '(E) Because the downward gravitational acceleration opposes upward vertical velocity during ascent, vertical speed $|v_y|$ decreases to zero at the apex, then increases continuously as the projectile falls. Horizontal speed remains strictly constant throughout.'),
  ('ap-topic-physc-kinematics-forces-energy_q11', 'ap-topic-physc-kinematics-forces-energy', 11, false, 'A', 'Trajectory Equation & Wall Clearance Angle', 'hard', 'An object is launched from the ground with speed $v$ at distance $d$ away from a wall of height $h$. Which equation gives the launch angle $\theta$ to just clear the wall?', '["$h = d\\tan\\theta - \\frac{gd^2}{2v^2\\cos^2\\theta}$","$h = d^2\\cos\\theta - \\frac{gd^2}{2v^2\\cos^2\\theta}$","$h = d\\tan\\theta - \\frac{gd^2}{2v\\cos\\theta}$","$h = d\\sin\\theta - \\frac{gd^2}{v^2\\cos^2\\theta}$","$h = d\\sin\\theta - \\frac{gd^2}{2v\\cos\\theta}$"]'::jsonb, '(A) Horizontal time to reach the wall: $t = \frac{d}{v\cos\theta}$.
Substituting into vertical position $y(t) = (v\sin\theta)t - \frac{1}{2}gt^2$:
  $$h = (v\sin\theta)\left(\frac{d}{v\cos\theta}\right) - \frac{1}{2}g\left(\frac{d}{v\cos\theta}\right)^2 = d\tan\theta - \frac{gd^2}{2v^2\cos^2\theta}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q12', 'ap-topic-physc-kinematics-forces-energy', 12, false, 'D', 'Velocity-Time Graph & Position Integral', 'medium', 'An object moves in a straight line with a given velocity-time graph. If $x = 3.0\text{ m}$ at $t = 0$, what is the position at $t = 3.0\text{ s}$ if the area under the $v\text{--}t$ curve from $0$ to $3\text{ s}$ is $8\text{ m}$?', '["$5\\text{ m}$","$8\\text{ m}$","$10\\text{ m}$","$11\\text{ m}$","$14\\text{ m}$"]'::jsonb, '(D) Displacement is the definite integral of velocity: $\Delta x = \int_0^3 v(t)\,dt = 8\text{ m}$.
  $$x(3) = x(0) + \Delta x = 3.0\text{ m} + 8\text{ m} = 11\text{ m}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q13', 'ap-topic-physc-kinematics-forces-energy', 13, false, 'E', 'Newton''s Third Law Action-Reaction Pairs', 'easy', 'A box is dragged across a table at constant velocity by a string. Which of the following is a Newton''s Third Law action-reaction pair?  I. Force of gravity on the box and normal force on the box  II. Force of friction on the box and tension force on the box  III. Force of the box pushing down on the table and normal force of the table pushing up on the box', '["I only","I and II only","II only","I and III only","III only"]'::jsonb, '(E) An action-reaction pair must involve mutual forces of the same physical type exerted between the same two objects in opposite directions. The table pushing up on the box ($F_{N,\text{table on box}}$) and the box pushing down on the table ($F_{N,\text{box on table}}$) act on each other, satisfying Newton''s Third Law.'),
  ('ap-topic-physc-kinematics-forces-energy_q14', 'ap-topic-physc-kinematics-forces-energy', 14, false, 'D', 'Apparent Weight in Accelerating Elevator', 'easy', 'A person who weighs $800\text{ N}$ steps onto a scale in an elevator accelerating upward at $5\text{ m/s}^2$. What will the scale read? ($g = 10\text{ m/s}^2$)', '["$400\\text{ N}$","$800\\text{ N}$","$1,000\\text{ N}$","$1,200\\text{ N}$","$1,600\\text{ N}$"]'::jsonb, '(D) Mass $m = \frac{W}{g} = \frac{800\text{ N}}{10\text{ m/s}^2} = 80\text{ kg}$.
Using Newton''s Second Law with upward as positive:
  $$F_N - mg = ma \implies F_N = m(g + a) = (80\text{ kg})(10 + 5\text{ m/s}^2) = 1,200\text{ N}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q15', 'ap-topic-physc-kinematics-forces-energy', 15, false, 'D', 'Two-Block System Tension & Acceleration', 'medium', 'A horizontal force of $20\text{ N}$ pulls on a $1.0\text{ kg}$ block attached by a string to a $2.0\text{ kg}$ block on a frictionless surface. Find the tension $F_T$ in the connecting string and the acceleration $a$ of the system.', '["$F_T = 13.3\\text{ N},\\ a = 10\\text{ m/s}^2$","$F_T = 13.3\\text{ N},\\ a = 20\\text{ m/s}^2$","$F_T = 15\\text{ N},\\ a = 6.7\\text{ m/s}^2$","$F_T = 13.3\\text{ N},\\ a = 6.7\\text{ m/s}^2$","$F_T = 20\\text{ N},\\ a = 6.7\\text{ m/s}^2$"]'::jsonb, '(D) System acceleration:
  $$a = \frac{F_{\text{applied}}}{m_1 + m_2} = \frac{20\text{ N}}{1.0 + 2.0\text{ kg}} = \frac{20}{3}\text{ m/s}^2 \approx 6.7\text{ m/s}^2$$
Tension pulling the trailing $2.0\text{ kg}$ block:
  $$F_T = m_2 a = (2.0\text{ kg})\left(\frac{20}{3}\text{ m/s}^2\right) = \frac{40}{3}\text{ N} \approx 13.3\text{ N}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q16', 'ap-topic-physc-kinematics-forces-energy', 16, false, 'C', 'Three-Block Frictionless Train Tensions', 'medium', 'A force of $20\text{ N}$ pulls a chain of three frictionless blocks: $3.0\text{ kg} - 2.0\text{ kg} - 1.0\text{ kg}$. Find $F_{T1}$ (between $1\text{ kg}$ and $2\text{ kg}$), $F_{T2}$ (between $2\text{ kg}$ and $3\text{ kg}$), and acceleration $a$.', '["$F_{T1} = 1\\text{ N},\\ a = 1\\text{ m/s}^2$","$F_{T1} = 3.3\\text{ N},\\ F_{T2} = 3.3\\text{ N},\\ a = 3.3\\text{ m/s}^2$","$F_{T1} = 3.3\\text{ N},\\ F_{T2} = 10\\text{ N},\\ a = 3.3\\text{ m/s}^2$","$F_{T1} = 3.3\\text{ N},\\ F_{T2} = 10\\text{ N},\\ a = 6.7\\text{ m/s}^2$","$F_{T1} = 10\\text{ N},\\ a = 6.7\\text{ m/s}^2$"]'::jsonb, '(C) $$a = \frac{20\text{ N}}{1.0 + 2.0 + 3.0\text{ kg}} = \frac{20}{6}\text{ m/s}^2 = 3.33\text{ m/s}^2$$
$$F_{T1} = m_1 a = (1.0\text{ kg})(3.33\text{ m/s}^2) = 3.33\text{ N}$$
$$F_{T2} = (m_1 + m_2)a = (1.0 + 2.0\text{ kg})(3.33\text{ m/s}^2) = 10.0\text{ N}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q17', 'ap-topic-physc-kinematics-forces-energy', 17, false, 'A', 'Incline Static Friction Threshold', 'medium', 'A box is placed at rest on a ramp ($\theta = 30^\circ, \mu_s = 0.5$). The box will:', '["Accelerate down the ramp","Accelerate briefly then stop","Move with constant velocity","Not move","Cannot be determined"]'::jsonb, '(A) Downhill gravitational component: $F_{g,\parallel} = mg\sin(30^\circ) = 0.50\,mg$.
Maximum static friction force:
  $$f_{s,\max} = \mu_s mg\cos(30^\circ) = (0.5)(0.866\,mg) \approx 0.433\,mg$$
Because $F_{g,\parallel} > f_{s,\max}$ ($0.50\,mg > 0.433\,mg$), the net force down the ramp is positive, and the box will accelerate down.'),
  ('ap-topic-physc-kinematics-forces-energy_q18', 'ap-topic-physc-kinematics-forces-energy', 18, false, 'C', 'Atwood Machine System Acceleration', 'easy', 'In an Atwood machine with hanging masses $m$ and $4m$, find the acceleration.', '["$0.2g$","$0.4g$","$0.6g$","$0.75g$","$0.8g$"]'::jsonb, '(C) $$a = \frac{m_2 - m_1}{m_1 + m_2}g = \frac{4m - m}{4m + m}g = \frac{3}{5}g = 0.6g$$')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-physc-kinematics-forces-energy_q19', 'ap-topic-physc-kinematics-forces-energy', 19, false, 'E', 'Two-Block System with Kinetic Friction', 'medium', 'A $20\text{ N}$ force pulls a $2.0\text{ kg}$ block connected to a $1.0\text{ kg}$ trailing block on a rough surface ($\mu_k = 0.2$). Find the tension $F_T$ and acceleration $a$ ($g = 10\text{ m/s}^2$).', '["$F_T = 1\\text{ N},\\ a = 4.7\\text{ m/s}^2$","$F_T = 3.3\\text{ N},\\ a = 4.7\\text{ m/s}^2$","$F_T = 3.3\\text{ N},\\ a = 6.7\\text{ m/s}^2$","$F_T = 6.7\\text{ N},\\ a = 6.7\\text{ m/s}^2$","$F_T = 6.7\\text{ N},\\ a = 4.7\\text{ m/s}^2$"]'::jsonb, '(E) Total friction force: $f_{\text{total}} = \mu_k(m_1 + m_2)g = (0.2)(3.0\text{ kg})(10\text{ m/s}^2) = 6\text{ N}$.
Acceleration: $a = \frac{F - f_{\text{total}}}{m_1 + m_2} = \frac{20 - 6}{3} = \frac{14}{3} \approx 4.7\text{ m/s}^2$.
Tension on the $1.0\text{ kg}$ trailing block:
  $$F_T - f_1 = m_1 a \implies F_T = (0.2)(1.0)(10) + (1.0)(4.7) = 2.0 + 4.7 = 6.7\text{ N}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q20', 'ap-topic-physc-kinematics-forces-energy', 20, false, 'B', 'Incline Gravitational Scaling', 'easy', 'An object slides down a frictionless incline of angle $\theta$ and reaches final speed $v$. On a planet with twice Earth''s gravitational acceleration ($2g$), what will be its final speed?', '["$v$","$\\sqrt{2}v$","$2v$","$4v$","$v/2$"]'::jsonb, '(B) Using $v = \sqrt{2ad} = \sqrt{2(g\sin\theta)d} \propto \sqrt{g}$. Doubling $g$ scales the final velocity by a factor of $\sqrt{2}$, giving $v_{\text{new}} = \sqrt{2}v$.'),
  ('ap-topic-physc-kinematics-forces-energy_q21', 'ap-topic-physc-kinematics-forces-energy', 21, false, 'B', 'Vertical Loop Minimum Cut-Off Speed', 'medium', 'A roller coaster completes a loop of radius $r = 25\text{ m}$. What is the minimum speed needed at the top of the loop for riders to remain safely in contact with the track? ($g = 10\text{ m/s}^2$)', '["$12.7\\text{ m/s}$","$15.8\\text{ m/s}$","$21.2\\text{ m/s}$","$29.3\\text{ m/s}$","$33.3\\text{ m/s}$"]'::jsonb, '(B) At critical cut-off speed, normal force $F_N \to 0$, so gravity alone provides the centripetal acceleration:
  $$\frac{mv^2}{r} = mg \implies v = \sqrt{gr} = \sqrt{(10\text{ m/s}^2)(25\text{ m})} = \sqrt{250} \approx 15.8\text{ m/s}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q22', 'ap-topic-physc-kinematics-forces-energy', 22, false, 'B', 'Vertical Circular Motion Bottom Tension', 'medium', 'A bucket of mass $3\text{ kg}$ on a $0.6\text{-m}$ rope is whirled in a vertical circle. At the lowest point, the tension is $50\text{ N}$. What is the speed of the bucket? ($g = 10\text{ m/s}^2$)', '["$1\\text{ m/s}$","$2\\text{ m/s}$","$3\\text{ m/s}$","$4\\text{ m/s}$","$5\\text{ m/s}$"]'::jsonb, '(B) At the bottom of the circle: $F_T - mg = \frac{mv^2}{r}$.
  $$50\text{ N} - (3\text{ kg})(10\text{ m/s}^2) = \frac{3 v^2}{0.6} \implies 20 = 5v^2 \implies v^2 = 4 \implies v = 2\text{ m/s}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q23', 'ap-topic-physc-kinematics-forces-energy', 23, false, 'C', 'Vertical String Circle Critical Apex Speed', 'medium', 'What is the critical speed at the top of the vertical circle for the bucket in Question 10 so the rope does not become slack?', '["$0.6\\text{ m/s}$","$1.8\\text{ m/s}$","$2.4\\text{ m/s}$","$3.2\\text{ m/s}$","$4.8\\text{ m/s}$"]'::jsonb, '(C) $$v_{\text{critical}} = \sqrt{gr} = \sqrt{(10\text{ m/s}^2)(0.60\text{ m})} = \sqrt{6.0} \approx 2.45\text{ m/s} \approx 2.4\text{ m/s}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q24', 'ap-topic-physc-kinematics-forces-energy', 24, false, 'D', 'Centripetal Acceleration & Angular Frequency', 'easy', 'An object moves at constant speed in a circular path of radius $r$ at 1 revolution per second. What is its centripetal acceleration?', '["$2\\pi r$","$2\\pi^2 r$","$2\\pi^2 r^2$","$4\\pi^2 r$","$4\\pi^2 r^2$"]'::jsonb, '(D) With angular frequency $\omega = 2\pi f = 2\pi(1) = 2\pi\text{ rad/s}$:
  $$a_c = \omega^2 r = (2\pi)^2 r = 4\pi^2 r$$'),
  ('ap-topic-physc-kinematics-forces-energy_q25', 'ap-topic-physc-kinematics-forces-energy', 25, false, 'A', 'Perpendicular Force & Zero Work', 'easy', 'A force $F = 20\text{ N}$ acts on a $3\text{ kg}$ object as it moves $4\text{ m}$. If $F$ is perpendicular to displacement, the work done is:', '["$0\\text{ J}$","$60\\text{ J}$","$80\\text{ J}$","$600\\text{ J}$","$2,400\\text{ J}$"]'::jsonb, '(A) $W = \vec{F}\cdot\vec{d} = F d \cos(90^\circ) = 0\text{ J}$. Any force acting strictly perpendicular to displacement performs zero work.'),
  ('ap-topic-physc-kinematics-forces-energy_q26', 'ap-topic-physc-kinematics-forces-energy', 26, false, 'B', 'Work-Energy Theorem & Kinetic Energy Change', 'easy', 'An object of mass $4\text{ kg}$ accelerates from $3\text{ m/s}$ to $6\text{ m/s}$ in $8\text{ s}$. How much work was done on the object?', '["$27\\text{ J}$","$54\\text{ J}$","$72\\text{ J}$","$96\\text{ J}$","Cannot be determined"]'::jsonb, '(B) By the Work-Energy Theorem ($W = \Delta K$):
  $$W = \frac{1}{2}m(v_f^2 - v_i^2) = \frac{1}{2}(4\text{ kg})((6\text{ m/s})^2 - (3\text{ m/s})^2) = 2(36 - 9) = 2(27) = 54\text{ J}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q27', 'ap-topic-physc-kinematics-forces-energy', 27, false, 'D', 'Path Independence & Conservative Gravitational Work', 'easy', 'To lift a box of mass $m$ to height $h$, three options are considered: Option 1 (direct lift), Option 2 ($30^\circ$ incline), Option 3 (pulley system). Compare the work done under ideal conditions.', '["Option 1 > Option 2 > Option 3","Option 1 > Option 2 = Option 3","Option 1 = Option 3 > Option 2","Option 1 = Option 2 = Option 3","Cannot be determined"]'::jsonb, '(D) Under ideal conservative conditions, gravitational potential energy is path-independent. In all three methods, the minimum work required is identical: $W = mgh$.'),
  ('ap-topic-physc-kinematics-forces-energy_q28', 'ap-topic-physc-kinematics-forces-energy', 28, false, 'E', 'Normal Force Zero Work on Incline', 'easy', 'A $4\text{ kg}$ box is pulled up a ramp ($\theta = 30^\circ$, height $= 5\text{ m}$) at constant velocity. How much work is done by the normal force?', '["$160\\text{ J}$","$80\\text{ J}$","$40\\text{ J}$","$20\\text{ J}$","$0\\text{ J}$"]'::jsonb, '(E) The normal force is perpendicular to the ramp surface and therefore perpendicular to the displacement vector of the box ($\theta = 90^\circ$). Thus $W_N = F_N d \cos(90^\circ) = 0\text{ J}$.'),
  ('ap-topic-physc-kinematics-forces-energy_q29', 'ap-topic-physc-kinematics-forces-energy', 29, false, 'A', 'Elevator Normal Force Positive Work', 'easy', 'A man stands in an elevator as it begins to ascend. Does the normal force from the floor do work on the man?', '["Yes, and the work done will be positive.","Yes, and the work done will be negative.","Yes, but the sign cannot be determined.","No, the normal force does no work in any situation.","No, normal force does no work here."]'::jsonb, '(A) The normal force pushes upward on the man''s feet ($\vec{F}_N$ is upward) and the elevator displacement is upward ($\vec{d}$ is upward). Because $\vec{F}_N$ and $\vec{d}$ point in the same direction ($\theta = 0^\circ$), $W = F_N d \cos(0^\circ) > 0$ (positive work).'),
  ('ap-topic-physc-kinematics-forces-energy_q30', 'ap-topic-physc-kinematics-forces-energy', 30, false, 'D', 'Frictionless Incline Energy Conservation', 'medium', 'A $3.5\text{ kg}$ block slides from rest down a frictionless $30^\circ$ incline of length $6.4\text{ m}$. What is its speed at the bottom? ($g = 10\text{ m/s}^2$)', '["$5.0\\text{ m/s}$","$5.7\\text{ m/s}$","$6.4\\text{ m/s}$","$8.0\\text{ m/s}$","$10\\text{ m/s}$"]'::jsonb, '(D) Vertical height of the incline: $h = L\sin(30^\circ) = 6.4(0.5) = 3.2\text{ m}$.
By Conservation of Energy:
  $$mgh = \frac{1}{2}mv^2 \implies v = \sqrt{2gh} = \sqrt{2(10)(3.2)} = \sqrt{64} = 8.0\text{ m/s}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q31', 'ap-topic-physc-kinematics-forces-energy', 31, false, 'D', 'Incline Kinetic Energy with Friction Work', 'medium', 'A block of mass $m$ slides from rest down an incline of length $s$ and height $h$ with kinetic friction force $F_f$. What is the kinetic energy at the bottom?', '["$mgh$","$mgh - F_f h$","$mgs - F_f h$","$mgh - F_f s$","$mgs - F_f s$"]'::jsonb, '(D) Applying the Work-Energy Theorem ($E_i + W_{\text{other}} = E_f$):
  $$mgh - F_f s = K_f \implies K_f = mgh - F_f s$$'),
  ('ap-topic-physc-kinematics-forces-energy_q32', 'ap-topic-physc-kinematics-forces-energy', 32, false, 'C', 'Newton''s Second Law with Aerodynamic Drag', 'easy', 'A $1,000\text{ kg}$ car accelerates at $4\text{ m/s}^2$ while experiencing $300\text{ N}$ of drag force. How much force must the engine produce?', '["$16,300\\text{ N}$","$15,700\\text{ N}$","$4,300\\text{ N}$","$4,000\\text{ N}$","$3,700\\text{ N}$"]'::jsonb, '(C) $$F_{\text{engine}} - F_{\text{drag}} = ma \implies F_{\text{engine}} = ma + F_{\text{drag}} = (1,000\text{ kg})(4\text{ m/s}^2) + 300\text{ N} = 4,300\text{ N}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q33', 'ap-topic-physc-kinematics-forces-energy', 33, false, 'E', 'Gravitational Free Fall Midpoint Speed Fraction', 'medium', 'An astronaut drops a rock from the top of a crater. When the rock is halfway down to the bottom, its speed is what fraction of its impact speed?', '["$1/4$","$1/2$","$1/\\sqrt{3}$","$\\sqrt{2}/3$","$1/\\sqrt{2}$"]'::jsonb, '(E) At halfway point $h/2$, kinetic energy is half the final kinetic energy: $K_{\text{mid}} = \frac{1}{2}K_{\text{final}}$.
  $$\frac{1}{2}mv_{\text{mid}}^2 = \frac{1}{2}\left(\frac{1}{2}mv_{\text{final}}^2\right) \implies v_{\text{mid}} = \frac{1}{\sqrt{2}}v_{\text{final}}$$'),
  ('ap-topic-physc-kinematics-forces-energy_q34', 'ap-topic-physc-kinematics-forces-energy', 34, false, 'D', 'Incline Constant Power Mechanical Derivation', 'hard', 'A block of mass $m$ is pulled up a ramp of length $d$, angle $\theta$, and friction coefficient $\mu$ by a motor at constant power in time $t$. What is the minimum power $P$?', '["$\\frac{md^2}{t^3} + \\frac{mgd\\sin\\theta}{t}$","$\\frac{md^2}{t^2} + mgd\\sin\\theta + \\mu mgd\\cos\\theta$","$\\frac{md^2}{t^3} + \\frac{mgd\\sin\\theta}{t} + \\frac{\\mu mgd\\cos\\theta}{t}$","$\\frac{2md^2}{t^3} + \\frac{mgd\\sin\\theta}{t} + \\frac{\\mu mgd\\cos\\theta}{t}$","$\\frac{md^2}{2t^3} + \\frac{mgd\\cos\\theta}{t} + \\frac{\\mu mgd\\sin\\theta}{t}$"]'::jsonb, '(D) Under constant acceleration to cover distance $d$ in time $t$, $d = \frac{1}{2}at^2 \implies a = \frac{2d}{t^2}$ and $v_f = \frac{2d}{t}$.
Total work done:
  $$W = \Delta K + \Delta U + W_{\text{friction}} = \frac{1}{2}m\left(\frac{2d}{t}\right)^2 + mg(d\sin\theta) + (\mu mg\cos\theta)d$$
Power $P = W/t$:
  $$P = \frac{2md^2}{t^3} + \frac{mgd\sin\theta}{t} + \frac{\mu mgd\cos\theta}{t}$$')
ON CONFLICT (id) DO NOTHING;

